window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch04"]={"id": "ch04", "title": "第四章 蛋白质结构预测与分析", "sub": "陈铭《生物信息学》第三版 · 科学出版社", "sub2": "复试生物信息学 · 逐章详解", "modules": [{"i": 0, "name": "第四章 蛋白质结构预测与分析", "slides": [{"i": 0, "sec": "第一节 蛋白质结构组织层次", "title": "蛋白质结构层次总览", "notes": "蛋白质结构具有丰富的组织层次，通常划分为一级、二级、超二级、结构域、三级和四级结构。一级结构指多肽链中氨基酸残基的排列顺序，由肽键共价连接，是决定更高层结构的主要因素；二级结构指主链局部有规律的构象，如α螺旋、β折叠、β转角和无规卷曲；超二级结构指相邻二级结构单元组合成的特定构象；结构域是三级结构中相对独立、常具有特定功能的区域；三级结构是整条肽链所有原子的三维空间排布；四级结构指多个亚基通过非共价键组装成的复合体。若两个蛋白质一级结构显著相似，通常认为它们同源。结构决定功能是蛋白质科学的首要法则。", "page": 60, "level": "掌握", "img": "assets/img/ch04/p060.jpg", "anim": null, "fig": null, "points": ["蛋白质结构层次：一级、二级、超二级、结构域、三级、四级结构。", "一级结构为多肽链中氨基酸残基的排列顺序，由肽键共价连接，是决定高级结构的主要因素。", "二级结构为主链局部有规律的构象，如α螺旋、β折叠、β转角和无规卷曲。", "超二级结构是相邻二级结构单元组合成的特定构象；结构域是三级结构中相对独立、常具特定功能的区域。", "三级结构是整条肽链所有原子的三维空间排布；四级结构是多个亚基通过非共价键组装成的特定空间排列。"], "check": {"q": "关于蛋白质结构层次，下列说法正确的是？", "o": ["A. 二级结构指多肽链中氨基酸残基的排列顺序", "B. 一级结构由肽键共价连接，是决定更高层结构的主要因素", "C. 四级结构指整条肽链所有原子的三维空间排布", "D. 结构域是多个亚基通过非共价键组装成的复合体"], "a": "B", "e": "一级结构指多肽链中氨基酸残基的排列顺序，由肽键共价连接，是决定更高层结构的主要因素。二级结构是主链局部有规律的构象；三级结构是整条肽链所有原子的三维空间排布；四级结构是多个亚基通过非共价键组装成的复合体。"}, "cards": [{"front": "蛋白质结构层次包括哪些？各层次的定义是什么？", "back": "蛋白质结构层次包括一级、二级、超二级、结构域、三级和四级结构。一级结构指多肽链中氨基酸残基的排列顺序，由肽键共价连接；二级结构指主链局部有规律的构象，如α螺旋、β折叠、β转角和无规卷曲；超二级结构指相邻二级结构单元组合成的特定构象；结构域是三级结构中相对独立、常具有特定功能的区域；三级结构是整条肽链所有原子的三维空间排布；四级结构指多个亚基通过非共价键组装成的特定空间排列。", "mnemonic": "一序二构超域三，四聚亚基功能全", "useImg": false}]}, {"i": 1, "sec": "第一节 蛋白质结构组织层次", "title": "α螺旋的结构特征", "notes": "α螺旋是蛋白质中最常见、最典型、含量最丰富的二级结构元件之一，属于重复性结构。其要点包括：主链骨架围绕中心轴盘绕形成右手螺旋；每上升一圈约含3.6个氨基酸残基，螺距约0.54 nm；相邻螺旋圈之间形成氢键，氢键方向大致平行于螺旋轴；侧链基团位于螺旋外侧。不利于α螺旋形成的因素主要有：存在侧链基团较大的氨基酸残基、连续存在带相同电荷的氨基酸残基、脯氨酸等破坏螺旋的残基。α螺旋常见于球状蛋白内部和跨膜蛋白的疏水区段，是结构预测中重点识别的二级结构类型。", "page": 61, "level": "掌握", "img": "assets/img/ch04/p061.jpg", "anim": null, "fig": null, "points": ["α螺旋是蛋白质中最常见、最典型、含量最丰富的二级结构元件之一，属于重复性结构。", "主链骨架围绕中心轴盘绕形成右手螺旋；每圈约含3.6个氨基酸残基，螺距约0.54 nm。", "相邻螺旋圈之间形成氢键，氢键方向大致平行于螺旋轴；侧链基团位于螺旋外侧。", "不利于α螺旋形成的因素：侧链基团较大的氨基酸残基、连续存在带相同电荷的氨基酸残基、脯氨酸等破坏螺旋的残基。", "α螺旋常见于球状蛋白内部和跨膜蛋白的跨膜区。"], "check": {"q": "关于α螺旋的结构特征，下列描述错误的是？", "o": ["A. 主链骨架围绕中心轴盘绕形成右手螺旋", "B. 每上升一圈约含3.6个氨基酸残基，螺距约0.54 nm", "C. 相邻螺旋圈之间形成氢键，氢键方向大致平行于螺旋轴", "D. 侧链基团位于螺旋内侧，以利于稳定螺旋"], "a": "D", "e": "α螺旋中侧链基团位于螺旋外侧，而不是内侧。其余选项均正确：α螺旋为右手螺旋，每圈约3.6个残基，螺距约0.54 nm，相邻螺旋圈之间形成大致平行于螺旋轴的氢键。"}, "cards": [{"front": "α螺旋的结构特征有哪些？哪些因素不利于α螺旋形成？", "back": "α螺旋是蛋白质中最常见、最典型、含量最丰富的二级结构元件之一，属于重复性结构。特征：主链骨架围绕中心轴盘绕形成右手螺旋；每上升一圈约含3.6个氨基酸残基，螺距约0.54 nm；相邻螺旋圈之间形成氢键，氢键方向大致平行于螺旋轴；侧链基团位于螺旋外侧。不利于α螺旋形成的因素：存在侧链基团较大的氨基酸残基、连续存在带相同电荷的氨基酸残基、脯氨酸等破坏螺旋的残基。", "mnemonic": "右手螺旋3.6，氢键平行侧链外；大侧同电脯氨酸，破坏螺旋要记牢", "useImg": false}]}, {"i": 2, "sec": "第一节 蛋白质结构组织层次", "title": "β折叠与β转角", "notes": "β折叠由Pauling等提出，是许多蛋白质中常见的二级结构。β折叠可分为平行式和反平行式：平行式中相邻肽链同向，反平行式中相邻肽链反向。每条肽链称为β折叠股，所有肽键的C=O和N—H之间形成链间氢键，侧链基团交替位于片层上下方。β转角常发生于多肽链180°回折处，通常由4个氨基酸残基构成，借第1和第4残基之间形成氢键，形成较稳定的紧密环，多存在于球状蛋白质分子表面，属于非重复性结构。无规卷曲则是主链骨架无规律盘绕的区段，常出现在螺旋与折叠之间，对连接和功能有重要作用。", "page": 62, "level": "掌握", "img": "assets/img/ch04/p062.jpg", "anim": null, "fig": null, "points": ["β折叠由Pauling等提出，是许多蛋白质中常见的二级结构，可分为平行式和反平行式。", "平行式中相邻肽链同向，反平行式中相邻肽链反向；每条肽链称为β折叠股。", "所有肽键的C=O和N—H之间形成链间氢键，侧链基团交替位于片层上下方。", "β转角常发生于多肽链180°回折处，通常由4个氨基酸残基构成，借第1和第4残基之间形成氢键，形成较稳定的紧密环。", "β转角多存在于球状蛋白质分子表面，属于非重复性结构；无规卷曲则是主链构象中没有规律性的部分。"], "check": {"q": "关于β折叠与β转角，下列说法正确的是？", "o": ["A. β折叠中所有肽键的C=O和N—H之间形成链内氢键", "B. 平行式β折叠中相邻肽链反向，反平行式中相邻肽链同向", "C. β转角通常由4个氨基酸残基构成，借第1和第4残基之间形成氢键", "D. β转角属于重复性结构，常出现在蛋白质疏水核心"], "a": "C", "e": "β转角常发生于多肽链180°回折处，通常由4个氨基酸残基构成，借第1和第4残基之间形成氢键，多存在于球状蛋白质分子表面，属于非重复性结构。β折叠中形成链间氢键；平行式相邻肽链同向，反平行式相邻肽链反向。"}, "cards": [{"front": "β折叠和β转角的结构特点是什么？", "back": "β折叠由Pauling等提出，是许多蛋白质中常见的二级结构，可分为平行式和反平行式：平行式中相邻肽链同向，反平行式中相邻肽链反向。每条肽链称为β折叠股，所有肽键的C=O和N—H之间形成链间氢键，侧链基团交替位于片层上下方。β转角常发生于多肽链180°回折处，通常由4个氨基酸残基构成，借第1和第4残基之间形成氢键，形成较稳定的紧密环，多存在于球状蛋白质分子表面，属于非重复性结构。", "mnemonic": "平行同向反平行，链间氢键侧链交替；转角四残回折处，1-4氢键稳定环", "useImg": false}]}, {"i": 3, "sec": "第一节 蛋白质结构组织层次", "title": "超二级结构与结构域", "notes": "超二级结构是介于二级结构和三级结构之间的组织层次，指若干相邻二级结构单元在空间上组合成特定的、可识别的构象单元，如βαβ、β发夹、螺旋-转角-螺旋等。结构域是三级结构中相对独立、紧密折叠的区域，常由多个超二级结构组成，往往具有特定功能，如结合配体、催化反应等。结构域是蛋白质功能与进化的基本单位之一，可通过序列比对和结构比较识别。在蛋白质结构预测中，识别结构域有助于功能注释、遗传操作目标确定以及药物靶点设计。结构域之间常由铰链区连接，允许相对运动。", "page": 63, "level": "理解", "img": "assets/img/ch04/p063.jpg", "anim": null, "fig": null, "points": ["超二级结构是介于二级结构和三级结构之间的组织层次，指若干相邻二级结构单元在空间上组合成特定的、可识别的构象单元。", "常见超二级结构包括βαβ、β发夹、螺旋-转角-螺旋等。", "结构域是三级结构中相对独立、紧密折叠的区域，常由多个超二级结构组成，往往具有特定功能。", "结构域是蛋白质功能与进化的基本单位之一，可通过序列比对和结构比较识别。", "在蛋白质结构预测中，识别结构域有助于功能注释、遗传操作目标确定以及药物设计。"], "check": {"q": "关于超二级结构与结构域，下列说法错误的是？", "o": ["A. 超二级结构是介于二级结构和三级结构之间的组织层次", "B. βαβ、β发夹、螺旋-转角-螺旋属于超二级结构", "C. 结构域是三级结构中相对独立、紧密折叠的区域，常具有特定功能", "D. 结构域之间不能由铰链区连接，因此结构域完全固定不动"], "a": "D", "e": "结构域之间常由铰链区连接，允许相对运动。超二级结构是若干相邻二级结构单元组合成的特定构象单元；结构域是三级结构中相对独立、紧密折叠且常具有特定功能的区域。"}, "cards": [{"front": "什么是超二级结构和结构域？它们在蛋白质结构预测中有何意义？", "back": "超二级结构是介于二级结构和三级结构之间的组织层次，指若干相邻二级结构单元在空间上组合成特定的、可识别的构象单元，如βαβ、β发夹、螺旋-转角-螺旋等。结构域是三级结构中相对独立、紧密折叠的区域，常由多个超二级结构组成，往往具有特定功能，如结合配体、催化反应等。结构域是蛋白质功能与进化的基本单位之一，可通过序列比对和结构比较识别。在蛋白质结构预测中，识别结构域有助于功能注释、遗传操作目标确定以及药物设计。", "mnemonic": "超二组合βαβ，结构域独立功能专；预测注释药物靶，进化功能基本单元", "useImg": false}]}, {"i": 4, "sec": "第一节 蛋白质结构组织层次", "title": "三级结构与四级结构", "notes": "三级结构指整条多肽链中所有原子的三维空间排布，是在二级结构和超二级结构基础上进一步折叠形成的完整构象。三级结构由一级结构决定，但受分子伴侣、环境条件等影响。四级结构指两个或多个具有独立三级结构的亚基通过非共价键（氢键、离子键、范德华力、疏水作用等）组装成的特定空间排列。亚基之间可相同（同源复合体）或不同（异源复合体）。四级结构是许多蛋白质行使功能所必需，如血红蛋白由四个亚基组成，具有协同结合氧的能力。结构决定功能，三级和四级结构直接决定蛋白质的生物学活性。", "page": 64, "level": "掌握", "img": "assets/img/ch04/p064.jpg", "anim": null, "fig": null, "points": ["三级结构指整条多肽链中所有原子的三维空间排布，是在二级结构和超二级结构基础上进一步折叠形成的完整构象。", "三级结构由一级结构决定，但受分子伴侣、环境条件等影响。", "四级结构指两个或多个具有独立三级结构的亚基通过非共价键组装成的特定空间排列。", "亚基之间可相同（同源复合体）或不同（异源复合体）。", "四级结构是许多蛋白质行使功能所必需，如血红蛋白由四个亚基组成，具有协同结合氧的能力。"], "check": {"q": "关于三级结构与四级结构，下列说法正确的是？", "o": ["A. 三级结构指多个亚基通过非共价键组装成的复合体", "B. 四级结构由一级结构直接决定，不受分子伴侣影响", "C. 四级结构中亚基之间只能相同，不能不同", "D. 血红蛋白由四个亚基组成，具有协同结合氧的能力"], "a": "D", "e": "三级结构指整条多肽链中所有原子的三维空间排布；四级结构指两个或多个具有独立三级结构的亚基通过非共价键组装成的特定空间排列。亚基可相同或不同。血红蛋白由四个亚基组成，具有协同结合氧的能力。"}, "cards": [{"front": "三级结构和四级结构有何区别与联系？", "back": "三级结构指整条多肽链中所有原子的三维空间排布，是在二级结构和超二级结构基础上进一步折叠形成的完整构象。三级结构由一级结构决定，但受分子伴侣、环境条件等影响。四级结构指两个或多个具有独立三级结构的亚基通过非共价键（氢键、离子键、范德华力、疏水作用等）组装成的特定空间排列。亚基之间可相同（同源复合体）或不同（异源复合体）。四级结构是许多蛋白质行使功能所必需，如血红蛋白由四个亚基组成，具有协同结合氧的能力。", "mnemonic": "三级单链全原子，四级多亚基非共价；同源异源复合体，血红蛋白协同氧", "useImg": false}]}, {"i": 5, "sec": "第二节 蛋白质结构的测定与理论预测", "title": "X射线晶体衍射法", "notes": "X射线晶体衍射法是测定蛋白质三维结构最重要的实验手段之一，可确定原子精度结构。其原理是利用X射线照射蛋白质晶体，通过衍射图谱计算电子密度，进而构建原子坐标。蛋白质晶体含大量无序水分子，常占晶胞50%~70%，保证晶体中结构与溶液结构相似。晶体中蛋白质仍可进行催化反应，且晶体结构具有很强生物相关性。该方法空间分辨率由X射线波长决定，原子位置精度受晶体衍射能力限制。当前结构基因组学推动自动化发展，如结晶机器人。但生产足够量、可溶、稳定、有活性的蛋白质仍是最大难题。", "page": 65, "level": "掌握", "img": "assets/img/ch04/p065.jpg", "anim": null, "fig": null, "points": ["X射线晶体衍射法是测定蛋白质三维结构最重要的实验手段之一，可确定原子精度结构。", "原理：利用X射线照射蛋白质晶体，通过衍射图谱计算电子密度，进而构建原子坐标。", "蛋白质晶体含大量无序水分子，常占晶胞50%~70%，保证晶体中结构与溶液结构相似。", "晶体中蛋白质仍可进行催化反应，且晶体结构具有很强生物相关性。", "空间分辨率由X射线波长决定，原子位置精度受晶体衍射能力限制；结构基因组学推动自动化发展。"], "check": {"q": "关于X射线晶体衍射法，下列说法正确的是？", "o": ["A. 蛋白质晶体中不含水分子，因此晶体结构与溶液结构差异很大", "B. 蛋白质晶体中蛋白质不能进行催化反应", "C. 该方法利用X射线照射蛋白质晶体，通过衍射图谱计算电子密度并构建原子坐标", "D. 该方法空间分辨率由蛋白质分子量决定，与X射线波长无关"], "a": "C", "e": "X射线晶体衍射法利用X射线照射蛋白质晶体，通过衍射图谱计算电子密度，进而构建原子坐标。蛋白质晶体含大量无序水分子，常占晶胞50%~70%，晶体中蛋白质仍可进行催化反应，晶体结构具有较强生物相关性。空间分辨率由X射线波长决定。"}, "cards": [{"front": "X射线晶体衍射法测定蛋白质结构的原理和特点是什么？", "back": "X射线晶体衍射法是测定蛋白质三维结构最重要的实验手段之一，可确定原子精度结构。原理：利用X射线照射蛋白质晶体，通过衍射图谱计算电子密度，进而构建原子坐标。蛋白质晶体含大量无序水分子，常占晶胞50%~70%，保证晶体中结构与溶液结构相似。晶体中蛋白质仍可进行催化反应，且晶体结构具有很强生物相关性。空间分辨率由X射线波长决定，原子位置精度受晶体衍射能力限制。当前结构基因组学推动自动化发展。", "mnemonic": "X射线照晶体，衍射图谱算电子；水占晶胞五到七，原子精度结构真", "useImg": false}]}, {"i": 6, "sec": "第二节 蛋白质结构的测定与理论预测", "title": "核磁共振法", "notes": "核磁共振法（NMR）用于测定溶液中蛋白质的三维构象，特别适合长度不超过150个氨基酸残基的小蛋白质。其原理是核磁矩不为零的核在外磁场中发生塞曼分裂，吸收特定射频辐射。NMR法不需要制备蛋白质晶体，可测定接近生理状态的溶液构象，能研究蛋白质与小分子作用的动力学过程，也可测定可变形的尾部构象，且属于非损伤性测定。常用实验包括TOCSY、NOESY等，通过计算和精修获得结构。NMR法对样品无破坏，但受蛋白质大小限制，且需要较高浓度和纯度。", "page": 66, "level": "理解", "img": "assets/img/ch04/p066.jpg", "anim": null, "fig": null, "points": ["蛋白质结构比对是对蛋白质三维空间结构的相似性进行比较，是蛋白质结构分析的重要手段。", "与序列比对相比，结构比对算法更复杂。", "标准结构比对结果包括：产生参数衡量结构相似性；产生两个蛋白质的序列比对结果；产生结构叠加后的PDB文件。", "结构比对可用于识别同源关系、分析进化关系、预测功能、评估结构预测模型等。", "常用方法包括基于距离矩阵、基于特征、基于几何等。"], "check": {"q": "关于核磁共振法（NMR），下列说法错误的是？", "o": ["A. NMR用于测定溶液中蛋白质的三维构象", "B. NMR特别适合长度不超过150个氨基酸残基的小蛋白质", "C. NMR需要制备高质量蛋白质晶体", "D. NMR可研究蛋白质与小分子作用的动力学过程"], "a": "C", "e": "NMR不需要制备蛋白质晶体，可测定接近生理状态的溶液构象。它特别适合长度不超过150个氨基酸残基的小蛋白质，可研究蛋白质与小分子作用的动力学过程，也可测定可变形的尾部构象，属于非损伤性测定。"}, "cards": [{"front": "核磁共振法（NMR）测定蛋白质结构的原理、适用条件和优缺点是什么？", "back": "核磁共振法（NMR）用于测定溶液中蛋白质的三维构象，特别适合长度不超过150个氨基酸残基的小蛋白质。原理：核磁矩不为零的核在外磁场中发生塞曼分裂，吸收特定射频辐射。NMR法不需要制备蛋白质晶体，可测定接近生理状态的溶液构象，能研究蛋白质与小分子作用的动力学过程，也可测定可变形的尾部构象，且属于非损伤性测定。常用实验包括TOCSY、NOESY等，通过计算和精修获得结构。NMR法对样品无破坏，但受蛋白质分子量限制。", "mnemonic": "NMR测溶液，小蛋白150；塞曼分裂射频吸，TOCSY NOESY精修", "useImg": false}, {"front": "冷冻电镜三维重构的原理、研究对象和优势是什么？", "back": "冷冻电子显微镜技术由de Rosier和Klug于1968年提出，20世纪80年代趋于成熟。该技术通过电子显微镜获取二维晶体图像，再经计算机图像处理重构三维结构。研究对象广泛，包括病毒、膜蛋白、肌丝、蛋白质核酸复合体、亚细胞器等。冷冻电镜可直接获得分子形态信息，即使在较低分辨率下也能提供有意义的结构信息。它适于捕捉动态结构变化，也适于解析难以结晶的膜蛋白和大分子复合体。电镜图像包含相位信息。", "mnemonic": "冷冻电镜二维像，计算机重构三维；病毒膜蛋白复合体，动态难结晶皆可解", "useImg": false}, {"front": "蛋白质结构比对的目的和意义是什么？标准结构比对结果包括哪些内容？", "back": "蛋白质结构比对是对蛋白质三维空间结构的相似性进行比较，是蛋白质结构分析的重要手段。与序列比对相比，结构比对算法更复杂。一个标准的结构比对结果包括：产生参数衡量结构相似性；产生两个蛋白质的序列比对结果，同一比对位置上的氨基酸意味着空间结构相似；产生结构叠加后的PDB文件，可通过图形显示软件观测相似性。结构比对可用于识别同源关系、分析进化关系、预测功能、评估结构预测模型等。常用方法包括基于距离矩阵、基于特征、基于几何等。", "mnemonic": "结构比对三维比，参数序列PDB；同源进化功能预测，评估模型方法多", "useImg": false}]}, {"i": 7, "sec": "第二节 蛋白质结构的测定与理论预测", "title": "冷冻电镜三维重构", "notes": "冷冻电子显微镜技术由de Rosier和Klug于1968年提出，20世纪80年代趋于成熟。该技术通过电子显微镜获取二维晶体图像，再经计算机图像处理重构三维结构。研究对象广泛，包括病毒、膜蛋白、肌丝、蛋白质核酸复合体、亚细胞器等。冷冻电镜可直接获得分子形态信息，即使在较低分辨率下也能提供有意义的结构信息。它适于捕捉动态结构变化，也适于解析难以结晶的膜蛋白和大分子复合体。电镜图像包含相位信息，在相位确定上比X射线晶体学更直接方便。近年来已成为继X射线和NMR之后生物大分子结构研究的重要方法。", "page": 66, "level": "理解", "img": "assets/img/ch04/p066.jpg", "anim": null, "fig": null, "points": ["蛋白质结构比对是对蛋白质三维空间结构的相似性进行比较，是蛋白质结构分析的重要手段。", "与序列比对相比，结构比对算法更复杂。", "标准结构比对结果包括：产生参数衡量结构相似性；产生两个蛋白质的序列比对结果；产生结构叠加后的PDB文件。", "结构比对可用于识别同源关系、分析进化关系、预测功能、评估结构预测模型等。", "常用方法包括基于距离矩阵、基于特征、基于几何等。"], "check": {"q": "关于冷冻电镜三维重构，下列说法正确的是？", "o": ["A. 该技术由de Rosier和Klug于1968年提出，20世纪80年代趋于成熟", "B. 该技术只能研究病毒，不能研究膜蛋白和大分子复合体", "C. 电镜图像不包含相位信息，因此相位确定比X射线晶体学更困难", "D. 该技术不能捕捉动态结构变化"], "a": "A", "e": "冷冻电子显微镜技术由de Rosier和Klug于1968年提出，20世纪80年代趋于成熟。研究对象广泛，包括病毒、膜蛋白、肌丝、蛋白质核酸复合体、亚细胞器等。电镜图像包含相位信息，在相位确定上比X射线晶体学更直接方便，也适于捕捉动态结构变化。"}, "cards": [{"front": "核磁共振法（NMR）测定蛋白质结构的原理、适用条件和优缺点是什么？", "back": "核磁共振法（NMR）用于测定溶液中蛋白质的三维构象，特别适合长度不超过150个氨基酸残基的小蛋白质。原理：核磁矩不为零的核在外磁场中发生塞曼分裂，吸收特定射频辐射。NMR法不需要制备蛋白质晶体，可测定接近生理状态的溶液构象，能研究蛋白质与小分子作用的动力学过程，也可测定可变形的尾部构象，且属于非损伤性测定。常用实验包括TOCSY、NOESY等，通过计算和精修获得结构。NMR法对样品无破坏，但受蛋白质分子量限制。", "mnemonic": "NMR测溶液，小蛋白150；塞曼分裂射频吸，TOCSY NOESY精修", "useImg": false}, {"front": "冷冻电镜三维重构的原理、研究对象和优势是什么？", "back": "冷冻电子显微镜技术由de Rosier和Klug于1968年提出，20世纪80年代趋于成熟。该技术通过电子显微镜获取二维晶体图像，再经计算机图像处理重构三维结构。研究对象广泛，包括病毒、膜蛋白、肌丝、蛋白质核酸复合体、亚细胞器等。冷冻电镜可直接获得分子形态信息，即使在较低分辨率下也能提供有意义的结构信息。它适于捕捉动态结构变化，也适于解析难以结晶的膜蛋白和大分子复合体。电镜图像包含相位信息。", "mnemonic": "冷冻电镜二维像，计算机重构三维；病毒膜蛋白复合体，动态难结晶皆可解", "useImg": false}, {"front": "蛋白质结构比对的目的和意义是什么？标准结构比对结果包括哪些内容？", "back": "蛋白质结构比对是对蛋白质三维空间结构的相似性进行比较，是蛋白质结构分析的重要手段。与序列比对相比，结构比对算法更复杂。一个标准的结构比对结果包括：产生参数衡量结构相似性；产生两个蛋白质的序列比对结果，同一比对位置上的氨基酸意味着空间结构相似；产生结构叠加后的PDB文件，可通过图形显示软件观测相似性。结构比对可用于识别同源关系、分析进化关系、预测功能、评估结构预测模型等。常用方法包括基于距离矩阵、基于特征、基于几何等。", "mnemonic": "结构比对三维比，参数序列PDB；同源进化功能预测，评估模型方法多", "useImg": false}]}, {"i": 8, "sec": "第二节 蛋白质结构的测定与理论预测", "title": "蛋白质结构比对的目的与意义", "notes": "蛋白质结构比对是对蛋白质三维空间结构的相似性进行比较，是蛋白质结构分析的重要手段。与序列比对相比，结构比对算法更复杂。一个标准的结构比对结果包括：产生参数衡量结构相似性；产生两个蛋白质的序列比对结果，同一比对位置上的氨基酸意味着空间结构相似；产生结构叠加后的PDB文件，可通过图形显示软件观测相似性。结构比对可用于识别同源关系、分析进化关系、预测功能、评估结构预测模型等。常用方法包括基于距离矩阵、基于几何特征等。结构比对是连接序列、结构与功能的重要桥梁。", "page": 66, "level": "理解", "img": "assets/img/ch04/p066.jpg", "anim": null, "fig": null, "points": ["蛋白质结构比对是对蛋白质三维空间结构的相似性进行比较，是蛋白质结构分析的重要手段。", "与序列比对相比，结构比对算法更复杂。", "标准结构比对结果包括：产生参数衡量结构相似性；产生两个蛋白质的序列比对结果；产生结构叠加后的PDB文件。", "结构比对可用于识别同源关系、分析进化关系、预测功能、评估结构预测模型等。", "常用方法包括基于距离矩阵、基于特征、基于几何等。"], "check": {"q": "关于蛋白质结构比对，下列说法错误的是？", "o": ["A. 结构比对是对蛋白质三维空间结构的相似性进行比较", "B. 标准结构比对结果可产生参数衡量结构相似性", "C. 结构比对可产生结构叠加后的PDB文件，便于图形显示软件观测相似性", "D. 结构比对算法通常比序列比对更简单"], "a": "D", "e": "与序列比对相比，结构比对算法更复杂。标准结构比对结果包括产生参数衡量结构相似性、产生两个蛋白质的序列比对结果、产生结构叠加后的PDB文件。结构比对可用于识别同源关系、分析进化关系、预测功能、评估结构预测模型等。"}, "cards": [{"front": "核磁共振法（NMR）测定蛋白质结构的原理、适用条件和优缺点是什么？", "back": "核磁共振法（NMR）用于测定溶液中蛋白质的三维构象，特别适合长度不超过150个氨基酸残基的小蛋白质。原理：核磁矩不为零的核在外磁场中发生塞曼分裂，吸收特定射频辐射。NMR法不需要制备蛋白质晶体，可测定接近生理状态的溶液构象，能研究蛋白质与小分子作用的动力学过程，也可测定可变形的尾部构象，且属于非损伤性测定。常用实验包括TOCSY、NOESY等，通过计算和精修获得结构。NMR法对样品无破坏，但受蛋白质分子量限制。", "mnemonic": "NMR测溶液，小蛋白150；塞曼分裂射频吸，TOCSY NOESY精修", "useImg": false}, {"front": "冷冻电镜三维重构的原理、研究对象和优势是什么？", "back": "冷冻电子显微镜技术由de Rosier和Klug于1968年提出，20世纪80年代趋于成熟。该技术通过电子显微镜获取二维晶体图像，再经计算机图像处理重构三维结构。研究对象广泛，包括病毒、膜蛋白、肌丝、蛋白质核酸复合体、亚细胞器等。冷冻电镜可直接获得分子形态信息，即使在较低分辨率下也能提供有意义的结构信息。它适于捕捉动态结构变化，也适于解析难以结晶的膜蛋白和大分子复合体。电镜图像包含相位信息。", "mnemonic": "冷冻电镜二维像，计算机重构三维；病毒膜蛋白复合体，动态难结晶皆可解", "useImg": false}, {"front": "蛋白质结构比对的目的和意义是什么？标准结构比对结果包括哪些内容？", "back": "蛋白质结构比对是对蛋白质三维空间结构的相似性进行比较，是蛋白质结构分析的重要手段。与序列比对相比，结构比对算法更复杂。一个标准的结构比对结果包括：产生参数衡量结构相似性；产生两个蛋白质的序列比对结果，同一比对位置上的氨基酸意味着空间结构相似；产生结构叠加后的PDB文件，可通过图形显示软件观测相似性。结构比对可用于识别同源关系、分析进化关系、预测功能、评估结构预测模型等。常用方法包括基于距离矩阵、基于特征、基于几何等。", "mnemonic": "结构比对三维比，参数序列PDB；同源进化功能预测，评估模型方法多", "useImg": false}]}, {"i": 9, "sec": "第三节 蛋白质对接", "title": "蛋白质相互作用的分类", "notes": "蛋白质相互作用指两个或多个蛋白质分子之间产生物理性接触。从复合体单体类型可分为同源相互作用和异源相互作用：同源复合体所有单体为同一种蛋白质，常见于酶、载体蛋白、转录调控因子；异源复合体包含不同蛋白质单体，常见于细胞信号传导通路。从稳定程度可分为稳固相互作用和瞬时相互作用：同源复合体多为稳固相互作用，信号传导中多为瞬时相互作用。从作用力可分为共价相互作用和非共价相互作用：共价相互作用主要由二硫键维持，较少见；非共价相互作用由氢键、离子键、范德华力或疏水作用维持，是主要形式。", "page": 79, "level": "掌握", "img": "assets/img/ch04/p079.jpg", "anim": null, "fig": null, "points": ["蛋白质对接是利用计算机预测两个已知结构的蛋白质在空间上如何结合。", "基本过程：已知两个蛋白质结构，搜索理论上可能产生的数百万个结合构象，利用生物信息学评价标准过滤排除不合理结构，对入围构象用精细能量函数打分，最终确定能量最低的构象。", "对接准确度取决于搜索结合构象的全面性和能量函数的合理性。", "搜索和排除主要考虑分子表面几何形状互补性和静电互补性。", "理论上分为刚性对接、半柔性对接和柔性对接：刚性对接中分子构象不变。"], "check": {"q": "关于蛋白质相互作用的分类，下列说法正确的是？", "o": ["A. 同源复合体包含不同蛋白质单体，常见于细胞信号传导通路", "B. 异源复合体所有单体为同一种蛋白质，常见于酶和转录调控因子", "C. 从稳定程度可分为稳固相互作用和瞬时相互作用，信号传导中多为瞬时相互作用", "D. 共价相互作用主要由氢键维持，在蛋白质相互作用中非常常见"], "a": "C", "e": "从稳定程度可分为稳固相互作用和瞬时相互作用，同源复合体多为稳固相互作用，信号传导中多为瞬时相互作用。同源复合体所有单体为同一种蛋白质；异源复合体包含不同蛋白质单体。共价相互作用主要由二硫键维持，较少见。"}, "cards": [{"front": "蛋白质相互作用如何分类？", "back": "蛋白质相互作用指两个或多个蛋白质分子之间产生物理性接触。从复合体单体类型可分为同源相互作用和异源相互作用：同源复合体所有单体为同一种蛋白质，常见于酶、载体蛋白、转录调控因子；异源复合体包含不同蛋白质单体，常见于细胞信号传导通路。从稳定程度可分为稳固相互作用和瞬时相互作用：同源复合体多为稳固相互作用，信号传导中多为瞬时相互作用。从作用力可分为共价相互作用和非共价相互作用：共价相互作用主要由二硫键维持。", "mnemonic": "同源异源看单体，稳固瞬时看稳定；共价非共价看作用，二硫键维持共价", "useImg": false}, {"front": "蛋白质对接的基本原理和分类是什么？", "back": "蛋白质对接是利用计算机预测两个已知结构的蛋白质在空间上如何结合。基本过程：已知两个蛋白质结构，搜索理论上可能产生的数百万个结合构象，利用生物信息学评价标准过滤排除不合理结构，对入围构象用精细能量函数打分，最终确定能量最低的构象。对接准确度取决于搜索结合构象的全面性和能量函数的合理性。搜索和排除主要考虑分子表面几何形状互补性和静电互补性。理论上分为刚性对接、半柔性对接和柔性对接：刚性对接中分子构象不变。", "mnemonic": "对接搜索百万构象，过滤打分能量最低；几何静电互补性，刚性半柔柔性分", "useImg": false}]}, {"i": 10, "sec": "第三节 蛋白质对接", "title": "蛋白质对接的基本原理与分类", "notes": "蛋白质对接是利用计算机预测两个已知结构的蛋白质在空间上如何结合。基本过程：已知两个蛋白质结构，搜索理论上可能产生的数百万个结合构象，利用生物信息学评价标准过滤排除不合理结构，对入围构象用精细能量函数打分，最终确定能量最低的构象。对接准确度取决于搜索结合构象的全面性和能量函数的合理性。搜索和排除主要考虑分子表面几何形状互补性和静电互补性。理论上分为刚性对接、半柔性对接和柔性对接：刚性对接中分子构象不变，仅改变空间位置与姿态，计算量小；半柔性对接允许指定片段构象变化，兼顾计算量与预测能力；柔性对接允许整个体系构象自由变化，计算量极大。", "page": 79, "level": "掌握", "img": "assets/img/ch04/p079.jpg", "anim": null, "fig": null, "points": ["蛋白质对接是利用计算机预测两个已知结构的蛋白质在空间上如何结合。", "基本过程：已知两个蛋白质结构，搜索理论上可能产生的数百万个结合构象，利用生物信息学评价标准过滤排除不合理结构，对入围构象用精细能量函数打分，最终确定能量最低的构象。", "对接准确度取决于搜索结合构象的全面性和能量函数的合理性。", "搜索和排除主要考虑分子表面几何形状互补性和静电互补性。", "理论上分为刚性对接、半柔性对接和柔性对接：刚性对接中分子构象不变。"], "check": {"q": "关于蛋白质对接的基本原理与分类，下列说法错误的是？", "o": ["A. 蛋白质对接是利用计算机预测两个已知结构的蛋白质在空间上如何结合", "B. 对接准确度取决于搜索结合构象的全面性和能量函数的合理性", "C. 搜索和排除主要考虑分子表面几何形状互补性和静电互补性", "D. 刚性对接中分子构象可自由改变，计算量最大"], "a": "D", "e": "刚性对接中分子构象不变，仅改变空间位置与姿态，计算量小。蛋白质对接基本过程包括搜索可能结合构象、利用生物信息学评价标准过滤、用精细能量函数打分并确定能量最低构象。"}, "cards": [{"front": "蛋白质相互作用如何分类？", "back": "蛋白质相互作用指两个或多个蛋白质分子之间产生物理性接触。从复合体单体类型可分为同源相互作用和异源相互作用：同源复合体所有单体为同一种蛋白质，常见于酶、载体蛋白、转录调控因子；异源复合体包含不同蛋白质单体，常见于细胞信号传导通路。从稳定程度可分为稳固相互作用和瞬时相互作用：同源复合体多为稳固相互作用，信号传导中多为瞬时相互作用。从作用力可分为共价相互作用和非共价相互作用：共价相互作用主要由二硫键维持。", "mnemonic": "同源异源看单体，稳固瞬时看稳定；共价非共价看作用，二硫键维持共价", "useImg": false}, {"front": "蛋白质对接的基本原理和分类是什么？", "back": "蛋白质对接是利用计算机预测两个已知结构的蛋白质在空间上如何结合。基本过程：已知两个蛋白质结构，搜索理论上可能产生的数百万个结合构象，利用生物信息学评价标准过滤排除不合理结构，对入围构象用精细能量函数打分，最终确定能量最低的构象。对接准确度取决于搜索结合构象的全面性和能量函数的合理性。搜索和排除主要考虑分子表面几何形状互补性和静电互补性。理论上分为刚性对接、半柔性对接和柔性对接：刚性对接中分子构象不变。", "mnemonic": "对接搜索百万构象，过滤打分能量最低；几何静电互补性，刚性半柔柔性分", "useImg": false}]}, {"i": 11, "sec": "第三节 蛋白质对接", "title": "常用蛋白质对接软件", "notes": "常用对接软件包括：ZDOCK，由美国马萨诸塞州立大学和波士顿大学开发，刚性对接，用户上传PDB文件或输入PDB ID，可选取必需或不允许参与结合的氨基酸，结果通过邮箱返回；GRAMMX，由堪萨斯大学开发，刚性对接，可指定必需参与结合的氨基酸，支持同源多聚对接；HADDOCK，由荷兰乌得勒支大学开发，半柔性对接，除几何形状和能量外，还参考生物化学和生物物理学实验数据，如NMR化学位移扰动、定点突变数据，可进行蛋白质-DNA、蛋白质-RNA、蛋白质-化合物对接；PDBePISA，在线交互式工具，可计算复合体相互作用面的原子数、氨基酸数、面积、溶剂化自由能、氢键、二硫键、盐键、共价键等。注意：对接只能预测已知有相互作用的蛋白质如何结合，不能预测是否有相互作用。", "page": 80, "level": "理解", "img": "assets/img/ch04/p080.jpg", "anim": null, "fig": null, "points": ["蛋白质折叠是指多肽链自发组装成特定三维空间结构的过程。", "Anfinsen原理指出，蛋白质的一级序列决定其特定的空间结构，一级序列折叠形成正确三维结构才使蛋白质具有正常生物学功能。", "若折叠在体内发生故障，形成错误空间结构，不仅丧失功能，还会引起疾病。", "由蛋白质异常三维结构引发的疾病统称为构象病，包括疯牛病、阿尔茨海默病、囊性纤维病变、家族性高胆固醇症、家族性淀粉样蛋白症、白内障及某些肿瘤等。", "这些疾病与蛋白质错误折叠和聚集密切相关。"], "check": {"q": "关于常用蛋白质对接软件，下列说法正确的是？", "o": ["A. ZDOCK由荷兰乌得勒支大学开发，属于半柔性对接", "B. GRAMMX由堪萨斯大学开发，属于刚性对接，可指定必需参与结合的氨基酸", "C. HADDOCK由美国马萨诸塞州立大学开发，属于刚性对接", "D. HADDOCK不能参考NMR化学位移扰动等实验数据"], "a": "B", "e": "GRAMMX由堪萨斯大学开发，为刚性对接，可指定必需参与结合的氨基酸，支持同源多聚对接。ZDOCK由美国马萨诸塞州立大学和波士顿大学开发，为刚性对接；HADDOCK由荷兰乌得勒支大学开发，为半柔性对接，可参考NMR化学位移扰动、定点突变数据等。"}, "cards": [{"front": "常用蛋白质对接软件有哪些？各自特点是什么？", "back": "常用对接软件包括：ZDOCK，由美国马萨诸塞州立大学和波士顿大学开发，刚性对接，用户上传PDB文件或输入PDB ID，可选取必需或不允许参与结合的氨基酸，结果通过邮箱返回；GRAMMX，由堪萨斯大学开发，刚性对接，可指定必需参与结合的氨基酸，支持同源多聚对接；HADDOCK，由荷兰乌得勒支大学开发，半柔性对接，除几何形状和能量外，还参考生物化学和生物物理学实验数据，如NMR化学位移扰动、定点突变数据。", "mnemonic": "ZDOCK刚性邮箱返，GRAMMX同源多聚；HADDOCK半柔参实验，NMR突变数据用", "useImg": false}, {"front": "什么是蛋白质折叠？什么是构象病？", "back": "蛋白质折叠是指多肽链自发组装成特定三维空间结构的过程。Anfinsen原理指出，蛋白质的一级序列决定其特定的空间结构，一级序列折叠形成正确三维结构才使蛋白质具有正常生物学功能。若折叠在体内发生故障，形成错误空间结构，不仅丧失功能，还会引起疾病。由蛋白质异常三维结构引发的疾病统称为构象病，包括疯牛病、阿尔茨海默病、囊性纤维病变、家族性高胆固醇症、家族性淀粉样蛋白症、白内障及某些肿瘤等。", "mnemonic": "折叠自发成三维，一级序列定空间；错误折叠构象病，疯牛阿尔茨海默", "useImg": false}]}, {"i": 12, "sec": "第四节 蛋白质折叠与疾病", "title": "蛋白质折叠的意义与构象病", "notes": "蛋白质折叠是指多肽链自发组装成特定三维空间结构的过程。Anfinsen原理指出，蛋白质的一级序列决定其特定的空间结构，一级序列折叠形成正确三维结构才使蛋白质具有正常生物学功能。若折叠在体内发生故障，形成错误空间结构，不仅丧失功能，还会引起疾病。由蛋白质异常三维结构引发的疾病统称为构象病，包括疯牛病、阿尔茨海默病、囊性纤维病变、家族性高胆固醇症、家族性淀粉样蛋白症、白内障及某些肿瘤等。这些疾病与蛋白质错误折叠、聚集或构象改变密切相关，是生物医学研究的重要领域。", "page": 80, "level": "掌握", "img": "assets/img/ch04/p080.jpg", "anim": null, "fig": null, "points": ["蛋白质折叠是指多肽链自发组装成特定三维空间结构的过程。", "Anfinsen原理指出，蛋白质的一级序列决定其特定的空间结构，一级序列折叠形成正确三维结构才使蛋白质具有正常生物学功能。", "若折叠在体内发生故障，形成错误空间结构，不仅丧失功能，还会引起疾病。", "由蛋白质异常三维结构引发的疾病统称为构象病，包括疯牛病、阿尔茨海默病、囊性纤维病变、家族性高胆固醇症、家族性淀粉样蛋白症、白内障及某些肿瘤等。", "这些疾病与蛋白质错误折叠和聚集密切相关。"], "check": {"q": "关于蛋白质折叠与构象病，下列说法错误的是？", "o": ["A. Anfinsen原理指出蛋白质的一级序列决定其特定空间结构", "B. 蛋白质折叠是指多肽链自发组装成特定三维空间结构的过程", "C. 构象病由蛋白质异常三维结构引发，包括疯牛病、阿尔茨海默病等", "D. 蛋白质错误折叠后仍保留正常生物学功能，只是结构略有不同"], "a": "D", "e": "若折叠在体内发生故障，形成错误空间结构，不仅丧失功能，还会引起疾病。由蛋白质异常三维结构引发的疾病统称为构象病，包括疯牛病、阿尔茨海默病、囊性纤维病变、家族性高胆固醇症、家族性淀粉样蛋白症、白内障及某些肿瘤等。"}, "cards": [{"front": "常用蛋白质对接软件有哪些？各自特点是什么？", "back": "常用对接软件包括：ZDOCK，由美国马萨诸塞州立大学和波士顿大学开发，刚性对接，用户上传PDB文件或输入PDB ID，可选取必需或不允许参与结合的氨基酸，结果通过邮箱返回；GRAMMX，由堪萨斯大学开发，刚性对接，可指定必需参与结合的氨基酸，支持同源多聚对接；HADDOCK，由荷兰乌得勒支大学开发，半柔性对接，除几何形状和能量外，还参考生物化学和生物物理学实验数据，如NMR化学位移扰动、定点突变数据。", "mnemonic": "ZDOCK刚性邮箱返，GRAMMX同源多聚；HADDOCK半柔参实验，NMR突变数据用", "useImg": false}, {"front": "什么是蛋白质折叠？什么是构象病？", "back": "蛋白质折叠是指多肽链自发组装成特定三维空间结构的过程。Anfinsen原理指出，蛋白质的一级序列决定其特定的空间结构，一级序列折叠形成正确三维结构才使蛋白质具有正常生物学功能。若折叠在体内发生故障，形成错误空间结构，不仅丧失功能，还会引起疾病。由蛋白质异常三维结构引发的疾病统称为构象病，包括疯牛病、阿尔茨海默病、囊性纤维病变、家族性高胆固醇症、家族性淀粉样蛋白症、白内障及某些肿瘤等。", "mnemonic": "折叠自发成三维，一级序列定空间；错误折叠构象病，疯牛阿尔茨海默", "useImg": false}]}, {"i": 13, "sec": "第四节 蛋白质折叠与疾病", "title": "Anfinsen热力学假说", "notes": "1963年，美国科学家Anfinsen发现还原变性的牛胰核糖核酸酶在去除变性剂和还原剂后，无需其他物质帮助即可折叠回原来的天然结构，且功能不丧失。由此提出蛋白质折叠的“热力学假说”：小型球状蛋白的天然折叠结构是热力学稳定态，即自由能全局最小状态；蛋白质一级结构序列所提供的全部信息可以完全且唯一地决定分子的天然结构，即一级结构决定高级结构。该假说得到许多体外实验证明，尤其对小分子质量蛋白质。Anfinsen因此获得1972年诺贝尔化学奖。这一思想长期构成从物理规律出发研究蛋白质折叠问题的基本出发点。", "page": 81, "level": "掌握", "img": "assets/img/ch04/p081.jpg", "anim": null, "fig": null, "points": ["1968年，Cyrus Levinthal提出利文索尔悖论：一条蛋白质序列可能的空间构象数天文数字，若逐一尝试所有构象寻找唯一天然态，所需时间远超宇宙年龄。", "例如100个氨基酸、每个3种构象，则有3^100种可能，每尝试一次耗10^-13秒，需3^100×10^-13秒，约10^34年。", "然而体外观测到的折叠时间为毫秒至秒，因此Levinthal认为蛋白质折叠必然按特定路径进行，强调动力学控制的重要性。", "折叠漏斗模型解释了蛋白质如何快速折叠到天然态：能量景观呈漏斗状，引导多肽链沿特定路径折叠。", "该悖论推动了蛋白质折叠动力学研究。"], "check": {"q": "关于Anfinsen热力学假说，下列说法正确的是？", "o": ["A. Anfinsen发现还原变性的牛胰核糖核酸酶必须依赖分子伴侣才能折叠回天然结构", "B. 小型球状蛋白的天然折叠结构是热力学稳定态，即自由能全局最小状态", "C. 蛋白质一级结构序列不能决定分子的天然结构", "D. Anfinsen因该研究获得1972年诺贝尔生理学或医学奖"], "a": "B", "e": "Anfinsen发现还原变性的牛胰核糖核酸酶在去除变性剂和还原剂后，无需其他物质帮助即可折叠回原来的天然结构。由此提出热力学假说：小型球状蛋白的天然折叠结构是热力学稳定态，即自由能全局最小状态；一级结构序列所提供的全部信息可以完全且唯一地决定分子的天然结构。Anfinsen获得1972年诺贝尔化学奖。"}, "cards": [{"front": "Anfinsen热力学假说的内容和实验依据是什么？", "back": "1963年，美国科学家Anfinsen发现还原变性的牛胰核糖核酸酶在去除变性剂和还原剂后，无需其他物质帮助即可折叠回原来的天然结构，且功能不丧失。由此提出蛋白质折叠的“热力学假说”：小型球状蛋白的天然折叠结构是热力学稳定态，即自由能全局最小状态；蛋白质一级结构序列所提供的全部信息可以完全且唯一地决定分子的天然结构，即一级结构决定高级结构。该假说得到许多体外实验证明，尤其对小分子质量蛋白质。", "mnemonic": "Anfinsen牛胰核糖酶，变性还原自复性；热力学假说自由能最小，一级序列定高级", "useImg": false}, {"front": "什么是Levinthal悖论？它说明了什么？", "back": "1968年，Cyrus Levinthal提出利文索尔悖论：一条蛋白质序列可能的空间构象数天文数字，若逐一尝试所有构象寻找唯一天然态，所需时间远超宇宙年龄。例如100个氨基酸、每个3种构象，则有3^100种可能，每尝试一次耗10^-13秒，需3^100×10^-13秒，约10^34年。然而体外观测到的折叠时间为毫秒至秒，因此Levinthal认为蛋白质折叠必然按特定路径进行，强调动力学控制的重要性。", "mnemonic": "Levinthal悖论：构象天文数字，逐一尝试超宇宙；折叠毫秒至秒，特定路径动力学", "useImg": false}]}, {"i": 14, "sec": "第四节 蛋白质折叠与疾病", "title": "Levinthal悖论与折叠漏斗", "notes": "1968年，Cyrus Levinthal提出利文索尔悖论：一条蛋白质序列可能的空间构象数天文数字，若逐一尝试所有构象寻找唯一天然态，所需时间远超宇宙年龄。例如100个氨基酸、每个3种构象，则有3^100种可能，每尝试一次耗10^-13秒，需3^100×10^-13秒，约10^34年。然而体外观测到的折叠时间为毫秒至秒，因此Levinthal认为蛋白质折叠必然按特定路径进行，强调动力学控制的重要性。1995年Wolynes等提出蛋白质折叠漏斗概念，调和热力学与动力学：漏斗状能量景观引导折叠快速趋向天然态，而非随机搜索。", "page": 81, "level": "理解", "img": "assets/img/ch04/p081.jpg", "anim": null, "fig": null, "points": ["1968年，Cyrus Levinthal提出利文索尔悖论：一条蛋白质序列可能的空间构象数天文数字，若逐一尝试所有构象寻找唯一天然态，所需时间远超宇宙年龄。", "例如100个氨基酸、每个3种构象，则有3^100种可能，每尝试一次耗10^-13秒，需3^100×10^-13秒，约10^34年。", "然而体外观测到的折叠时间为毫秒至秒，因此Levinthal认为蛋白质折叠必然按特定路径进行，强调动力学控制的重要性。", "折叠漏斗模型解释了蛋白质如何快速折叠到天然态：能量景观呈漏斗状，引导多肽链沿特定路径折叠。", "该悖论推动了蛋白质折叠动力学研究。"], "check": {"q": "关于Levinthal悖论与折叠漏斗，下列说法错误的是？", "o": ["A. Levinthal悖论指出蛋白质可能的空间构象数天文数字，逐一尝试所需时间远超宇宙年龄", "B. 体外观测到的折叠时间为毫秒至秒，说明蛋白质折叠必然按特定路径进行", "C. Levinthal强调动力学控制的重要性", "D. 1995年Wolynes等提出蛋白质折叠必须逐一尝试所有构象才能找到天然态"], "a": "D", "e": "1995年Wolynes等提出蛋白质折叠漏斗模型，而不是认为必须逐一尝试所有构象。Levinthal悖论指出，若逐一尝试所有构象寻找唯一天然态，所需时间远超宇宙年龄；但体外观测到的折叠时间为毫秒至秒，因此Levinthal认为蛋白质折叠必然按特定路径进行，强调动力学控制的重要性。"}, "cards": [{"front": "Anfinsen热力学假说的内容和实验依据是什么？", "back": "1963年，美国科学家Anfinsen发现还原变性的牛胰核糖核酸酶在去除变性剂和还原剂后，无需其他物质帮助即可折叠回原来的天然结构，且功能不丧失。由此提出蛋白质折叠的“热力学假说”：小型球状蛋白的天然折叠结构是热力学稳定态，即自由能全局最小状态；蛋白质一级结构序列所提供的全部信息可以完全且唯一地决定分子的天然结构，即一级结构决定高级结构。该假说得到许多体外实验证明，尤其对小分子质量蛋白质。", "mnemonic": "Anfinsen牛胰核糖酶，变性还原自复性；热力学假说自由能最小，一级序列定高级", "useImg": false}, {"front": "什么是Levinthal悖论？它说明了什么？", "back": "1968年，Cyrus Levinthal提出利文索尔悖论：一条蛋白质序列可能的空间构象数天文数字，若逐一尝试所有构象寻找唯一天然态，所需时间远超宇宙年龄。例如100个氨基酸、每个3种构象，则有3^100种可能，每尝试一次耗10^-13秒，需3^100×10^-13秒，约10^34年。然而体外观测到的折叠时间为毫秒至秒，因此Levinthal认为蛋白质折叠必然按特定路径进行，强调动力学控制的重要性。", "mnemonic": "Levinthal悖论：构象天文数字，逐一尝试超宇宙；折叠毫秒至秒，特定路径动力学", "useImg": false}]}, {"i": 15, "sec": "第四节 蛋白质折叠与疾病", "title": "分子伴侣与折叠辅助", "notes": "许多蛋白质在体内折叠需要分子伴侣帮助。分子伴侣是一类协助蛋白质正确折叠、组装、转运和降解的蛋白质，但不构成最终结构。常见分子伴侣包括热激蛋白Hsp70、Hsp60、Hsp90等。它们通过识别暴露的疏水表面，防止错误聚集，提供隔离环境促进正确折叠。分子伴侣消耗ATP，属于主动过程。分子伴侣功能异常与多种疾病相关。此外，蛋白质二硫键异构酶（PDI）和肽基脯氨酰顺反异构酶（PPI）也协助折叠。理解分子伴侣有助于解释体内折叠速率远高于体外、以及构象病的发生机制。", "page": 82, "level": "理解", "img": "assets/img/ch04/p082.jpg", "anim": null, "fig": null, "points": ["许多蛋白质在体内折叠需要分子伴侣帮助。", "分子伴侣是一类协助蛋白质正确折叠、组装、转运和降解的蛋白质，但不构成最终结构。", "常见分子伴侣包括热激蛋白Hsp70、Hsp60、Hsp90等。", "它们通过识别暴露的疏水表面，防止错误聚集，提供隔离环境促进正确折叠；分子伴侣消耗ATP，属于主动过程。", "分子伴侣功能异常与多种疾病相关；此外，蛋白质二硫键异构酶（PDI）和肽基脯氨酰顺反异构酶（PPI）也协助折叠。"], "check": {"q": "关于分子伴侣与折叠辅助，下列说法正确的是？", "o": ["A. 分子伴侣构成蛋白质最终结构的一部分", "B. 常见分子伴侣包括Hsp70、Hsp60、Hsp90等", "C. 分子伴侣协助折叠不消耗ATP，属于被动过程", "D. PDI和PPI与蛋白质折叠无关"], "a": "B", "e": "分子伴侣是一类协助蛋白质正确折叠、组装、转运和降解的蛋白质，但不构成最终结构。常见分子伴侣包括热激蛋白Hsp70、Hsp60、Hsp90等。它们通过识别暴露的疏水表面，防止错误聚集，提供隔离环境促进正确折叠，并消耗ATP，属于主动过程。PDI和PPI也协助折叠。"}, "cards": [{"front": "什么是分子伴侣？常见分子伴侣有哪些？它们如何协助蛋白质折叠？", "back": "许多蛋白质在体内折叠需要分子伴侣帮助。分子伴侣是一类协助蛋白质正确折叠、组装、转运和降解的蛋白质，但不构成最终结构。常见分子伴侣包括热激蛋白Hsp70、Hsp60、Hsp90等。它们通过识别暴露的疏水表面，防止错误聚集，提供隔离环境促进正确折叠。分子伴侣消耗ATP，属于主动过程。分子伴侣功能异常与多种疾病相关。此外，蛋白质二硫键异构酶（PDI）和肽基脯氨酰顺反异构酶（PPI）也协助折叠。", "mnemonic": "分子伴侣助折叠，不构成终结构；Hsp70 60 90，识别疏水耗ATP；PDI PPI也协助", "useImg": false}]}, {"i": 16, "sec": "第四节 蛋白质折叠与疾病", "title": "蛋白质结构预测的意义与挑战", "notes": "蛋白质结构预测旨在从氨基酸序列预测三维结构，弥补实验测定结构数量远少于序列数量的缺口。实验方法如X射线晶体衍射、NMR、冷冻电镜虽能获得高分辨率结构，但耗时、昂贵且受样品限制。理论预测方法包括同源建模、折叠识别、从头预测等。同源建模基于序列相似性，适用于有同源结构的情况；折叠识别适用于序列相似性低但结构相似的情况；从头预测基于物理化学原理和能量函数。近年来深度学习方法如AlphaFold取得突破。结构预测有助于功能注释、药物设计、蛋白质改造。但准确预测仍面临构象搜索空间巨大、能量函数不完善等挑战。", "page": 83, "level": "掌握", "img": "assets/img/ch04/p083.jpg", "anim": null, "fig": null, "points": ["蛋白质结构预测旨在从氨基酸序列预测三维结构，弥补实验测定结构数量远少于序列数量的缺口。", "实验方法如X射线晶体衍射、NMR、冷冻电镜虽能获得高分辨率结构，但耗时、昂贵且受样品限制。", "理论预测方法包括同源建模、折叠识别、从头预测等。", "同源建模基于序列相似性，适用于有同源结构的情况；折叠识别适用于序列相似性低但结构相似的情况；从头预测基于物理化学原理和能量函数。", "近年来深度学习方法如AlphaFold取得突破，显著提高了预测精度。"], "check": {"q": "关于蛋白质结构预测的意义与挑战，下列说法错误的是？", "o": ["A. 蛋白质结构预测旨在从氨基酸序列预测三维结构", "B. 实验测定结构数量远少于序列数量，结构预测可弥补这一缺口", "C. 同源建模适用于序列相似性低但结构相似的情况", "D. 深度学习方法如AlphaFold在蛋白质结构预测中取得突破"], "a": "C", "e": "同源建模基于序列相似性，适用于有同源结构的情况；折叠识别适用于序列相似性低但结构相似的情况；从头预测基于物理化学原理和能量函数。实验方法如X射线晶体衍射、NMR、冷冻电镜虽能获得高分辨率结构，但耗时、昂贵且受样品限制。"}, "cards": [{"front": "蛋白质结构预测的意义、挑战和主要方法是什么？", "back": "蛋白质结构预测旨在从氨基酸序列预测三维结构，弥补实验测定结构数量远少于序列数量的缺口。实验方法如X射线晶体衍射、NMR、冷冻电镜虽能获得高分辨率结构，但耗时、昂贵且受样品限制。理论预测方法包括同源建模、折叠识别、从头预测等。同源建模基于序列相似性，适用于有同源结构的情况；折叠识别适用于序列相似性低但结构相似的情况；从头预测基于物理化学原理和能量函数。近年来深度学习方法如AlphaFold取得突破。", "mnemonic": "结构预测补缺口，实验耗时贵受限；同源折叠从头法，AlphaFold突破深", "useImg": false}]}, {"i": 17, "sec": "第四节 蛋白质折叠与疾病", "title": "蛋白质结构预测与疾病研究", "notes": "蛋白质错误折叠与构象病密切相关，结构预测可用于研究疾病机制。例如，预测突变对蛋白质结构稳定性的影响，识别致病构象变化；预测淀粉样纤维形成倾向；设计稳定化突变以治疗构象病。此外，结构预测有助于理解蛋白质-蛋白质相互作用异常在疾病中的作用，为药物设计提供靶点。结合分子动力学模拟，可研究折叠路径和中间体。生物信息学工具如PolyPhen、SIFT可预测突变有害性。结构预测与实验方法结合，可加速疾病相关蛋白质的结构解析和药物开发。", "page": 84, "level": "理解", "img": "assets/img/ch04/p084.jpg", "anim": null, "fig": null, "points": ["蛋白质错误折叠与构象病密切相关，结构预测可用于研究疾病机制。", "例如，预测突变对蛋白质结构稳定性的影响，识别致病构象变化；预测淀粉样纤维形成倾向；设计稳定化突变以治疗构象病。", "结构预测有助于理解蛋白质-蛋白质相互作用异常在疾病中的作用，为药物设计提供靶点。", "结合分子动力学模拟，可研究折叠路径和中间体。", "生物信息学工具如PolyPhen、SIFT可预测突变有害性；结构预测与实验方法结合，可加速疾病相关蛋白质研究。"], "check": {"q": "关于蛋白质结构预测与疾病研究，下列说法正确的是？", "o": ["A. 结构预测不能用于研究突变对蛋白质结构稳定性的影响", "B. PolyPhen、SIFT可用于预测突变有害性", "C. 结构预测无助于理解蛋白质-蛋白质相互作用异常在疾病中的作用", "D. 分子动力学模拟不能用于研究折叠路径和中间体"], "a": "B", "e": "生物信息学工具如PolyPhen、SIFT可预测突变有害性。结构预测可用于研究疾病机制，例如预测突变对蛋白质结构稳定性的影响、识别致病构象变化、预测淀粉样纤维形成倾向、设计稳定化突变以治疗构象病，并有助于理解蛋白质-蛋白质相互作用异常在疾病中的作用。结合分子动力学模拟，可研究折叠路径和中间体。"}, "cards": [{"front": "蛋白质结构预测在疾病研究中有哪些应用？", "back": "蛋白质错误折叠与构象病密切相关，结构预测可用于研究疾病机制。例如，预测突变对蛋白质结构稳定性的影响，识别致病构象变化；预测淀粉样纤维形成倾向；设计稳定化突变以治疗构象病。此外，结构预测有助于理解蛋白质-蛋白质相互作用异常在疾病中的作用，为药物设计提供靶点。结合分子动力学模拟，可研究折叠路径和中间体。生物信息学工具如PolyPhen、SIFT可预测突变有害性。结构预测与实验方法结合，可加速疾病相关蛋白质研究。", "mnemonic": "结构预测研疾病，突变稳定致病构象；淀粉样纤维倾向，药物靶点分子动力学；PolyPhen SIFT预测害", "useImg": false}]}], "mcq": [{"id": "ch04_mcq_1", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "关于蛋白质二级结构，以下哪项描述是正确的？", "o": ["A. α螺旋每圈含3.6个氨基酸残基，螺距约0.54 nm，侧链位于螺旋外侧", "B. β折叠中平行式相邻肽链反向，反平行式相邻肽链同向", "C. β转角通常由6个氨基酸残基构成，借第1和第6残基之间形成氢键", "D. 无规卷曲是主链骨架有规律盘绕的重复性结构"], "a": "A", "e": "A正确：α螺旋每圈3.6个残基，螺距0.54 nm，侧链位于外侧。B错误：平行式同向，反平行式反向。C错误：β转角通常由4个残基构成，第1和第4残基间形成氢键。D错误：无规卷曲是无规律盘绕，非重复性结构。", "kp": "ch04_s0_0"}, {"id": "ch04_mcq_2", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "蛋白质结构层次中，介于二级结构和三级结构之间的是？", "o": ["A. 一级结构", "B. 超二级结构和结构域", "C. 四级结构", "D. 无规卷曲"], "a": "B", "e": "超二级结构和结构域介于二级结构和三级结构之间。一级结构是氨基酸序列；四级结构是亚基组装；无规卷曲属于二级结构的一种。", "kp": "ch04_s0_0"}, {"id": "ch04_mcq_3", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "X射线晶体衍射法测定蛋白质结构时，蛋白质晶体中水分子通常占晶胞的多少？", "o": ["A. 10%~20%", "B. 30%~40%", "C. 50%~70%", "D. 80%~90%"], "a": "C", "e": "蛋白质晶体中水分子常占晶胞的50%~70%，保证晶体中结构与溶液结构相似。", "kp": "ch04_s0_5"}, {"id": "ch04_mcq_4", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "NMR法测定蛋白质三维结构的限制是？", "o": ["A. 仅适用于长度不超过150个氨基酸残基的小蛋白质", "B. 需要制备高质量蛋白质晶体", "C. 对样品有破坏性", "D. 不能测定溶液中的构象"], "a": "A", "e": "NMR法仅限于分析长度不超过150个氨基酸残基的小蛋白质。它不需要晶体，非损伤性，可测定溶液构象。", "kp": "ch04_s0_16"}, {"id": "ch04_mcq_5", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "冷冻电镜三维重构技术的优势不包括？", "o": ["A. 适于解析难以结晶的膜蛋白和大分子复合体", "B. 可直接获得分子形态信息", "C. 电镜图像包含相位信息，相位确定比X射线晶体学直接方便", "D. 仅适用于小分子蛋白质，分辨率低于NMR"], "a": "D", "e": "冷冻电镜适于膜蛋白、大分子复合体，可直接获得形态信息，相位确定方便。它不限于小分子蛋白质，且分辨率可很高。", "kp": "ch04_s0_7"}, {"id": "ch04_mcq_6", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "蛋白质对接的基本过程中，最终确定结合构象的依据是？", "o": ["A. 分子表面几何形状互补性最大", "B. 静电互补性最强", "C. 能量函数打分最低", "D. 搜索到的构象数量最多"], "a": "C", "e": "对接过程：搜索构象，过滤不合理结构，对入围构象用精细能量函数打分，最终确定能量最低的构象。几何形状和静电互补用于搜索和排除，不是最终依据。", "kp": "ch04_s0_10"}, {"id": "ch04_mcq_7", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "以下哪个软件是半柔性蛋白质对接软件，且可参考生物化学实验数据？", "o": ["A. ZDOCK", "B. GRAMMX", "C. HADDOCK", "D. PDBePISA"], "a": "C", "e": "HADDOCK是半柔性对接软件，参考NMR化学位移扰动、定点突变等实验数据。ZDOCK和GRAMMX是刚性对接，PDBePISA是相互作用分析工具。", "kp": "ch04_s0_11"}, {"id": "ch04_mcq_8", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "Anfinsen提出的蛋白质折叠“热力学假说”核心内容是？", "o": ["A. 蛋白质折叠需要分子伴侣帮助", "B. 蛋白质一级结构序列完全且唯一地决定天然结构", "C. 蛋白质折叠按特定动力学路径进行", "D. 蛋白质天然结构是自由能局部最小状态"], "a": "B", "e": "Anfinsen热力学假说认为小型球状蛋白天然结构是自由能全局最小状态，一级结构序列完全且唯一决定天然结构。C是Levinthal的观点，D应为全局最小。", "kp": "ch04_s0_13"}, {"id": "ch04_mcq_9", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "Levinthal悖论说明的问题是？", "o": ["A. 蛋白质折叠速度极快，不可能通过随机搜索所有构象完成", "B. 蛋白质折叠不需要能量", "C. 蛋白质一级结构不能决定高级结构", "D. 分子伴侣是折叠必需的"], "a": "A", "e": "Levinthal悖论指出，若蛋白质通过随机尝试所有构象寻找天然态，所需时间远超宇宙年龄，但实际折叠时间很短，说明折叠必然按特定路径进行，强调动力学控制。", "kp": "ch04_s0_14"}, {"id": "ch04_mcq_10", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "以下哪项属于构象病？", "o": ["A. 糖尿病", "B. 阿尔茨海默病", "C. 高血压", "D. 贫血"], "a": "B", "e": "构象病由蛋白质异常三维结构引发，包括疯牛病、阿尔茨海默病、囊性纤维病变、家族性高胆固醇症、家族性淀粉样蛋白症、白内障及某些肿瘤等。", "kp": "ch04_s0_12"}], "judge": [{"id": "ch04_judge_1", "modI": 0, "q": "蛋白质一级结构由肽键共价连接，是决定更高层结构的主要因素。", "a": "对", "e": "一级结构指多肽链中氨基酸残基的排列顺序，由肽键共价连接，是决定更高层结构的主要因素。", "kp": "ch04_s0_0"}, {"id": "ch04_judge_2", "modI": 0, "q": "α螺旋是左手螺旋，每圈约含3.6个氨基酸残基。", "a": "错", "e": "α螺旋是右手螺旋，每上升一圈约含3.6个氨基酸残基，螺距约0.54 nm。", "kp": "ch04_s0_1"}, {"id": "ch04_judge_3", "modI": 0, "q": "β折叠中所有肽键的C=O和N—H之间形成链间氢键，侧链基团交替位于片层上下方。", "a": "对", "e": "β折叠由平行或反平行β折叠股组成，链间氢键由肽键C=O和N—H形成，侧链交替位于片层上下方。", "kp": "ch04_s0_2"}, {"id": "ch04_judge_4", "modI": 0, "q": "β转角通常由4个氨基酸残基构成，借第1和第4残基之间形成氢键。", "a": "对", "e": "β转角常发生于180°回折处，通常由4个氨基酸残基构成，第1和第4残基之间形成氢键，形成较稳定的紧密环。", "kp": "ch04_s0_2"}, {"id": "ch04_judge_5", "modI": 0, "q": "结构域是二级结构中相对独立、紧密折叠的区域，常由多个超二级结构组成。", "a": "错", "e": "结构域是三级结构中相对独立、紧密折叠的区域，常由多个超二级结构组成，往往具有特定功能。", "kp": "ch04_s0_3"}, {"id": "ch04_judge_6", "modI": 0, "q": "四级结构指两个或多个具有独立三级结构的亚基通过非共价键组装成的特定空间排列。", "a": "对", "e": "四级结构由多个亚基通过非共价键（氢键、离子键、范德华力、疏水作用等）组装而成，亚基可相同或不同。", "kp": "ch04_s0_4"}, {"id": "ch04_judge_7", "modI": 0, "q": "X射线晶体衍射法中，蛋白质晶体含大量无序水分子，常占晶胞50%~70%，保证晶体中结构与溶液结构相似。", "a": "对", "e": "蛋白质晶体含大量无序水分子，常占晶胞50%~70%，保证晶体中结构与溶液结构相似，且晶体中蛋白质仍可进行催化反应。", "kp": "ch04_s0_5"}, {"id": "ch04_judge_8", "modI": 0, "q": "核磁共振法特别适合长度超过150个氨基酸残基的大蛋白质。", "a": "错", "e": "核磁共振法特别适合长度不超过150个氨基酸残基的小蛋白质，受蛋白质大小限制。", "kp": "ch04_s0_6"}, {"id": "ch04_judge_9", "modI": 0, "q": "冷冻电镜可直接获得分子形态信息，即使在较低分辨率下也能提供有意义的结构信息。", "a": "对", "e": "冷冻电镜可直接获得分子形态信息，即使在较低分辨率下也能提供有意义的结构信息，适于捕捉动态结构变化和解析难以结晶的膜蛋白及大分子复合体。", "kp": "ch04_s0_7"}, {"id": "ch04_judge_10", "modI": 0, "q": "蛋白质对接可以预测两个蛋白质之间是否有相互作用。", "a": "错", "e": "对接只能预测已知有相互作用的蛋白质如何结合，不能预测是否有相互作用。", "kp": "ch04_s0_9"}], "fill": [{"id": "ch04_fill_1", "modI": 0, "q": "蛋白质一级结构指多肽链中氨基酸残基的________，由________共价连接。", "a": "排列顺序,肽键", "kp": "ch04_s0_0"}, {"id": "ch04_fill_2", "modI": 0, "q": "α螺旋每上升一圈约含________个氨基酸残基，螺距约________ nm。", "a": "3.6,0.54", "kp": "ch04_s0_1"}, {"id": "ch04_fill_3", "modI": 0, "q": "β折叠可分为________式和________式，前者相邻肽链同向，后者相邻肽链反向。", "a": "平行,反平行", "kp": "ch04_s0_2"}, {"id": "ch04_fill_4", "modI": 0, "q": "β转角通常由________个氨基酸残基构成，借第1和第4残基之间形成________。", "a": "4,氢键", "kp": "ch04_s0_2"}, {"id": "ch04_fill_5", "modI": 0, "q": "结构域是三级结构中相对独立、紧密折叠的区域，常由多个________组成，往往具有特定________。", "a": "超二级结构,功能", "kp": "ch04_s0_3"}, {"id": "ch04_fill_6", "modI": 0, "q": "四级结构指两个或多个具有独立三级结构的亚基通过________键组装成的特定空间排列。", "a": "非共价", "kp": "ch04_s0_4"}, {"id": "ch04_fill_7", "modI": 0, "q": "Anfinsen原理指出，蛋白质的________决定其特定的空间结构，________折叠形成正确三维结构才使蛋白质具有正常生物学功能。", "a": "一级序列,一级序列", "kp": "ch04_s0_12"}, {"id": "ch04_fill_8", "modI": 0, "q": "蛋白质对接理论上分为________对接、半柔性对接和________对接。", "a": "刚性,柔性", "kp": "ch04_s0_10"}], "short": [{"id": "ch04_short_1", "modI": 0, "q": "简述蛋白质结构层次及其相互关系。", "a": "蛋白质结构层次通常划分为一级、二级、超二级、结构域、三级和四级结构。一级结构指多肽链中氨基酸残基的排列顺序，由肽键共价连接，是决定更高层结构的主要因素；二级结构指主链局部有规律的构象，如α螺旋、β折叠、β转角和无规卷曲；超二级结构指相邻二级结构单元组合成的特定构象；结构域是三级结构中相对独立、常具有特定功能的区域；三级结构是整条肽链所有原子的三维空间排布；四级结构指多个亚基通过非共价键组装成的复合体。若两个蛋白质一级结构显著相似，通常认为它们同源。结构决定功能是蛋白质科学的首要法则。", "kp": "ch04_s0_0"}, {"id": "ch04_short_2", "modI": 0, "q": "简述α螺旋的结构特征及不利于其形成的因素。", "a": "α螺旋是蛋白质中最常见、最典型、含量最丰富的二级结构元件之一，属于重复性结构。其要点包括：主链骨架围绕中心轴盘绕形成右手螺旋；每上升一圈约含3.6个氨基酸残基，螺距约0.54 nm；相邻螺旋圈之间形成氢键，氢键方向大致平行于螺旋轴；侧链基团位于螺旋外侧。不利于α螺旋形成的因素主要有：存在侧链基团较大的氨基酸残基、连续存在带相同电荷的氨基酸残基、脯氨酸等破坏螺旋的残基。α螺旋常见于球状蛋白内部和跨膜蛋白的疏水区段，是结构预测中重点识别的二级结构类型。", "kp": "ch04_s0_1"}, {"id": "ch04_short_3", "modI": 0, "q": "简述β折叠与β转角的区别。", "a": "β折叠由Pauling等提出，是许多蛋白质中常见的二级结构。β折叠可分为平行式和反平行式：平行式中相邻肽链同向，反平行式中相邻肽链反向。每条肽链称为β折叠股，所有肽键的C=O和N—H之间形成链间氢键，侧链基团交替位于片层上下方。β转角常发生于多肽链180°回折处，通常由4个氨基酸残基构成，借第1和第4残基之间形成氢键，形成较稳定的紧密环，多存在于球状蛋白质分子表面，属于非重复性结构。无规卷曲则是主链骨架无规律盘绕的区段，常出现在螺旋与折叠之间，对连接和功能有重要作用。", "kp": "ch04_s0_2"}, {"id": "ch04_short_4", "modI": 0, "q": "简述蛋白质结构比对的目的与意义。", "a": "蛋白质结构比对是对蛋白质三维空间结构的相似性进行比较，是蛋白质结构分析的重要手段。与序列比对相比，结构比对算法更复杂。一个标准的结构比对结果包括：产生参数衡量结构相似性；产生两个蛋白质的序列比对结果，同一比对位置上的氨基酸意味着空间结构相似；产生结构叠加后的PDB文件，可通过图形显示软件观测相似性。结构比对可用于识别同源关系、分析进化关系、预测功能、评估结构预测模型等。常用方法包括基于距离矩阵、基于几何特征等。结构比对是连接序列、结构与功能的重要桥梁。", "kp": "ch04_s0_8"}, {"id": "ch04_short_5", "modI": 0, "q": "简述蛋白质对接的基本原理与分类。", "a": "蛋白质对接是利用计算机预测两个已知结构的蛋白质在空间上如何结合。基本过程：已知两个蛋白质结构，搜索理论上可能产生的数百万个结合构象，利用生物信息学评价标准过滤排除不合理结构，对入围构象用精细能量函数打分，最终确定能量最低的构象。对接准确度取决于搜索结合构象的全面性和能量函数的合理性。搜索和排除主要考虑分子表面几何形状互补性和静电互补性。理论上分为刚性对接、半柔性对接和柔性对接：刚性对接中分子构象不变，仅改变空间位置与姿态，计算量小；半柔性对接允许指定片段构象变化，兼顾计算量与预测能力；柔性对接允许整个体系构象自由变化，计算量极大。", "kp": "ch04_s0_10"}], "calc": [{"id": "ch04_calc_1", "modI": 0, "q": "论述蛋白质折叠的意义、Anfinsen热力学假说及Levinthal悖论，并说明折叠漏斗如何调和热力学与动力学。", "a": "蛋白质折叠是指多肽链自发组装成特定三维空间结构的过程。Anfinsen原理指出，蛋白质的一级序列决定其特定的空间结构，一级序列折叠形成正确三维结构才使蛋白质具有正常生物学功能。若折叠在体内发生故障，形成错误空间结构，不仅丧失功能，还会引起疾病。由蛋白质异常三维结构引发的疾病统称为构象病，包括疯牛病、阿尔茨海默病、囊性纤维病变、家族性高胆固醇症、家族性淀粉样蛋白症、白内障及某些肿瘤等。1963年，美国科学家Anfinsen发现还原变性的牛胰核糖核酸酶在去除变性剂和还原剂后，无需其他物质帮助即可折叠回原来的天然结构，且功能不丧失。由此提出蛋白质折叠的“热力学假说”：小型球状蛋白的天然折叠结构是热力学稳定态，即自由能全局最小状态；蛋白质一级结构序列所提供的全部信息可以完全且唯一地决定分子的天然结构，即一级结构决定高级结构。该假说得到许多体外实验证明，尤其对小分子质量蛋白质。Anfinsen因此获得1972年诺贝尔化学奖。1968年，Cyrus Levinthal提出利文索尔悖论：一条蛋白质序列可能的空间构象数天文数字，若逐一尝试所有构象寻找唯一天然态，所需时间远超宇宙年龄。例如100个氨基酸、每个3种构象，则有3^100种可能，每尝试一次耗10^-13秒，需3^100×10^-13秒，约10^34年。然而体外观测到的折叠时间为毫秒至秒，因此Levinthal认为蛋白质折叠必然按特定路径进行，强调动力学控制的重要性。1995年Wolynes等提出蛋白质折叠漏斗概念，调和热力学与动力学：漏斗状能量景观引导折叠快速趋向天然态，而非随机搜索。", "steps": "1. 蛋白质折叠定义与意义；2. Anfinsen热力学假说内容与实验依据；3. Levinthal悖论的计算与含义；4. 折叠漏斗概念及其对热力学与动力学的调和。", "kp": "ch04_s0_14"}, {"id": "ch04_calc_2", "modI": 0, "q": "论述蛋白质结构预测的意义、主要方法及面临的挑战，并说明其在疾病研究中的应用。", "a": "蛋白质结构预测旨在从氨基酸序列预测三维结构，弥补实验测定结构数量远少于序列数量的缺口。实验方法如X射线晶体衍射、NMR、冷冻电镜虽能获得高分辨率结构，但耗时、昂贵且受样品限制。理论预测方法包括同源建模、折叠识别、从头预测等。同源建模基于序列相似性，适用于有同源结构的情况；折叠识别适用于序列相似性低但结构相似的情况；从头预测基于物理化学原理和能量函数。近年来深度学习方法如AlphaFold取得突破。结构预测有助于功能注释、药物设计、蛋白质改造。但准确预测仍面临构象搜索空间巨大、能量函数不完善等挑战。蛋白质错误折叠与构象病密切相关，结构预测可用于研究疾病机制。例如，预测突变对蛋白质结构稳定性的影响，识别致病构象变化；预测淀粉样纤维形成倾向；设计稳定化突变以治疗构象病。此外，结构预测有助于理解蛋白质-蛋白质相互作用异常在疾病中的作用，为药物设计提供靶点。结合分子动力学模拟，可研究折叠路径和中间体。生物信息学工具如PolyPhen、SIFT可预测突变有害性。结构预测与实验方法结合，可加速疾病相关蛋白质的结构解析和药物开发。", "steps": "1. 结构预测的意义与实验方法局限；2. 主要预测方法：同源建模、折叠识别、从头预测、深度学习；3. 挑战：构象搜索空间、能量函数；4. 在疾病研究中的应用：突变影响、淀粉样纤维、稳定化突变、药物靶点、与实验结合。", "kp": "ch04_s0_16"}], "term": [{"id": "ch04_term_1", "modI": 0, "term": "Protein primary structure", "def": "蛋白质一级结构：指多肽链中氨基酸残基的线性排列顺序；由肽键共价连接；是决定更高层次结构的主要因素；序列相似性常用于推断同源性。", "kp": "ch04_s0_14"}, {"id": "ch04_term_2", "modI": 0, "term": "Protein secondary structure", "def": "蛋白质二级结构：指主链局部有规律的构象；常见类型包括α螺旋、β折叠、β转角和无规卷曲；主要由主链原子间氢键维持；是结构预测中重点识别的元件。", "kp": "ch04_s0_13"}, {"id": "ch04_term_3", "modI": 0, "term": "α-helix", "def": "α螺旋：蛋白质中常见且含量丰富的二级结构元件；主链骨架围绕中心轴形成右手螺旋；每圈约3.6个氨基酸残基，螺距约0.54 nm；相邻螺旋圈之间形成氢键，氢键方向大致平行于螺旋轴；侧链基团位于螺旋外侧；连续相同电荷残基、大侧链残基和脯氨酸不利于其形成。", "kp": "ch04_s0_2"}, {"id": "ch04_term_4", "modI": 0, "term": "β-sheet", "def": "β折叠：由Pauling等提出的常见二级结构；可分为平行式和反平行式；平行式中相邻肽链同向，反平行式中相邻肽链反向；每条肽链称为β折叠股；所有肽键的C=O和N—H之间形成链间氢键；侧链基团交替位于片层上下方。", "kp": "ch04_s0_17"}, {"id": "ch04_term_5", "modI": 0, "term": "β-turn", "def": "β转角：常发生于多肽链180°回折处；通常由4个氨基酸残基构成；借第1和第4残基之间形成氢键；形成较稳定的紧密环；多存在于球状蛋白质分子表面；属于非重复性结构。", "kp": "ch04_s0_0"}, {"id": "ch04_term_6", "modI": 0, "term": "Supersecondary structure", "def": "超二级结构：介于二级结构和三级结构之间的组织层次；指若干相邻二级结构单元在空间上组合成特定的、可识别的构象单元；如βαβ、β发夹、螺旋-转角-螺旋等。", "kp": "ch04_s0_13"}, {"id": "ch04_term_7", "modI": 0, "term": "Protein domain", "def": "结构域：三级结构中相对独立、紧密折叠的区域；常由多个超二级结构组成；往往具有特定功能，如结合配体、催化反应等；是蛋白质功能与进化的基本单位之一；可通过序列比对和结构比较识别；结构域之间常由铰链区连接，允许相对运动。", "kp": "ch04_s0_13"}, {"id": "ch04_term_8", "modI": 0, "term": "Protein tertiary structure", "def": "蛋白质三级结构：指整条多肽链中所有原子的三维空间排布；是在二级结构和超二级结构基础上进一步折叠形成的完整构象；由一级结构决定，但受分子伴侣、环境条件等影响。", "kp": "ch04_s0_14"}, {"id": "ch04_term_9", "modI": 0, "term": "Protein quaternary structure", "def": "蛋白质四级结构：指两个或多个具有独立三级结构的亚基通过非共价键组装成的特定空间排列；非共价键包括氢键、离子键、范德华力、疏水作用等；亚基之间可相同（同源复合体）或不同（异源复合体）；是许多蛋白质行使功能所必需。", "kp": "ch04_s0_14"}, {"id": "ch04_term_10", "modI": 0, "term": "X-ray crystallography", "def": "X射线晶体衍射法：测定蛋白质三维结构最重要的实验手段之一；利用X射线照射蛋白质晶体，通过衍射图谱计算电子密度，进而构建原子坐标；蛋白质晶体含大量无序水分子，常占晶胞50%~70%；晶体中蛋白质仍可进行催化反应；空间分辨率由X射线波长决定，原子位置精度受晶体衍射能力限制；生产足够量、可溶、稳定、有活性的蛋白质仍是最大难题。", "kp": "ch04_s0_14"}, {"id": "ch04_term_11", "modI": 0, "term": "NMR spectroscopy", "def": "核磁共振法：用于测定溶液中蛋白质的三维构象；特别适合长度不超过150个氨基酸残基的小蛋白质；原理是核磁矩不为零的核在外磁场中发生塞曼分裂，吸收特定射频辐射；不需要制备蛋白质晶体；可测定接近生理状态的溶液构象；能研究蛋白质与小分子作用的动力学过程；也可测定可变形的尾部构象；属于非损伤性测定；常用实验包括TOCSY、NOESY等；受蛋白质大小限制，且需要较高浓度和纯度。", "kp": "ch04_s0_7"}, {"id": "ch04_term_12", "modI": 0, "term": "Cryo-electron microscopy", "def": "冷冻电镜三维重构：由de Rosier和Klug于1968年提出，20世纪80年代趋于成熟；通过电子显微镜获取二维晶体图像，再经计算机图像处理重构三维结构；研究对象包括病毒、膜蛋白、肌丝、蛋白质核酸复合体、亚细胞器等；可直接获得分子形态信息；适于捕捉动态结构变化，也适于解析难以结晶的膜蛋白和大分子复合体；电镜图像包含相位信息，在相位确定上比X射线晶体学更直接方便；已成为继X射线和NMR之后生物大分子结构研究的重要方法。", "kp": "ch04_s0_1"}]}], "mcq": [{"id": "ch04_mcq_1", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "关于蛋白质二级结构，以下哪项描述是正确的？", "o": ["A. α螺旋每圈含3.6个氨基酸残基，螺距约0.54 nm，侧链位于螺旋外侧", "B. β折叠中平行式相邻肽链反向，反平行式相邻肽链同向", "C. β转角通常由6个氨基酸残基构成，借第1和第6残基之间形成氢键", "D. 无规卷曲是主链骨架有规律盘绕的重复性结构"], "a": "A", "e": "A正确：α螺旋每圈3.6个残基，螺距0.54 nm，侧链位于外侧。B错误：平行式同向，反平行式反向。C错误：β转角通常由4个残基构成，第1和第4残基间形成氢键。D错误：无规卷曲是无规律盘绕，非重复性结构。", "kp": "ch04_s0_0"}, {"id": "ch04_mcq_2", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "蛋白质结构层次中，介于二级结构和三级结构之间的是？", "o": ["A. 一级结构", "B. 超二级结构和结构域", "C. 四级结构", "D. 无规卷曲"], "a": "B", "e": "超二级结构和结构域介于二级结构和三级结构之间。一级结构是氨基酸序列；四级结构是亚基组装；无规卷曲属于二级结构的一种。", "kp": "ch04_s0_0"}, {"id": "ch04_mcq_3", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "X射线晶体衍射法测定蛋白质结构时，蛋白质晶体中水分子通常占晶胞的多少？", "o": ["A. 10%~20%", "B. 30%~40%", "C. 50%~70%", "D. 80%~90%"], "a": "C", "e": "蛋白质晶体中水分子常占晶胞的50%~70%，保证晶体中结构与溶液结构相似。", "kp": "ch04_s0_5"}, {"id": "ch04_mcq_4", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "NMR法测定蛋白质三维结构的限制是？", "o": ["A. 仅适用于长度不超过150个氨基酸残基的小蛋白质", "B. 需要制备高质量蛋白质晶体", "C. 对样品有破坏性", "D. 不能测定溶液中的构象"], "a": "A", "e": "NMR法仅限于分析长度不超过150个氨基酸残基的小蛋白质。它不需要晶体，非损伤性，可测定溶液构象。", "kp": "ch04_s0_16"}, {"id": "ch04_mcq_5", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "冷冻电镜三维重构技术的优势不包括？", "o": ["A. 适于解析难以结晶的膜蛋白和大分子复合体", "B. 可直接获得分子形态信息", "C. 电镜图像包含相位信息，相位确定比X射线晶体学直接方便", "D. 仅适用于小分子蛋白质，分辨率低于NMR"], "a": "D", "e": "冷冻电镜适于膜蛋白、大分子复合体，可直接获得形态信息，相位确定方便。它不限于小分子蛋白质，且分辨率可很高。", "kp": "ch04_s0_7"}, {"id": "ch04_mcq_6", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "蛋白质对接的基本过程中，最终确定结合构象的依据是？", "o": ["A. 分子表面几何形状互补性最大", "B. 静电互补性最强", "C. 能量函数打分最低", "D. 搜索到的构象数量最多"], "a": "C", "e": "对接过程：搜索构象，过滤不合理结构，对入围构象用精细能量函数打分，最终确定能量最低的构象。几何形状和静电互补用于搜索和排除，不是最终依据。", "kp": "ch04_s0_10"}, {"id": "ch04_mcq_7", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "以下哪个软件是半柔性蛋白质对接软件，且可参考生物化学实验数据？", "o": ["A. ZDOCK", "B. GRAMMX", "C. HADDOCK", "D. PDBePISA"], "a": "C", "e": "HADDOCK是半柔性对接软件，参考NMR化学位移扰动、定点突变等实验数据。ZDOCK和GRAMMX是刚性对接，PDBePISA是相互作用分析工具。", "kp": "ch04_s0_11"}, {"id": "ch04_mcq_8", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "Anfinsen提出的蛋白质折叠“热力学假说”核心内容是？", "o": ["A. 蛋白质折叠需要分子伴侣帮助", "B. 蛋白质一级结构序列完全且唯一地决定天然结构", "C. 蛋白质折叠按特定动力学路径进行", "D. 蛋白质天然结构是自由能局部最小状态"], "a": "B", "e": "Anfinsen热力学假说认为小型球状蛋白天然结构是自由能全局最小状态，一级结构序列完全且唯一决定天然结构。C是Levinthal的观点，D应为全局最小。", "kp": "ch04_s0_13"}, {"id": "ch04_mcq_9", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "Levinthal悖论说明的问题是？", "o": ["A. 蛋白质折叠速度极快，不可能通过随机搜索所有构象完成", "B. 蛋白质折叠不需要能量", "C. 蛋白质一级结构不能决定高级结构", "D. 分子伴侣是折叠必需的"], "a": "A", "e": "Levinthal悖论指出，若蛋白质通过随机尝试所有构象寻找天然态，所需时间远超宇宙年龄，但实际折叠时间很短，说明折叠必然按特定路径进行，强调动力学控制。", "kp": "ch04_s0_14"}, {"id": "ch04_mcq_10", "mod": "第四章 蛋白质结构预测与分析", "modI": 0, "q": "以下哪项属于构象病？", "o": ["A. 糖尿病", "B. 阿尔茨海默病", "C. 高血压", "D. 贫血"], "a": "B", "e": "构象病由蛋白质异常三维结构引发，包括疯牛病、阿尔茨海默病、囊性纤维病变、家族性高胆固醇症、家族性淀粉样蛋白症、白内障及某些肿瘤等。", "kp": "ch04_s0_12"}], "judge": [{"id": "ch04_judge_1", "modI": 0, "q": "蛋白质一级结构由肽键共价连接，是决定更高层结构的主要因素。", "a": "对", "e": "一级结构指多肽链中氨基酸残基的排列顺序，由肽键共价连接，是决定更高层结构的主要因素。", "kp": "ch04_s0_0"}, {"id": "ch04_judge_2", "modI": 0, "q": "α螺旋是左手螺旋，每圈约含3.6个氨基酸残基。", "a": "错", "e": "α螺旋是右手螺旋，每上升一圈约含3.6个氨基酸残基，螺距约0.54 nm。", "kp": "ch04_s0_1"}, {"id": "ch04_judge_3", "modI": 0, "q": "β折叠中所有肽键的C=O和N—H之间形成链间氢键，侧链基团交替位于片层上下方。", "a": "对", "e": "β折叠由平行或反平行β折叠股组成，链间氢键由肽键C=O和N—H形成，侧链交替位于片层上下方。", "kp": "ch04_s0_2"}, {"id": "ch04_judge_4", "modI": 0, "q": "β转角通常由4个氨基酸残基构成，借第1和第4残基之间形成氢键。", "a": "对", "e": "β转角常发生于180°回折处，通常由4个氨基酸残基构成，第1和第4残基之间形成氢键，形成较稳定的紧密环。", "kp": "ch04_s0_2"}, {"id": "ch04_judge_5", "modI": 0, "q": "结构域是二级结构中相对独立、紧密折叠的区域，常由多个超二级结构组成。", "a": "错", "e": "结构域是三级结构中相对独立、紧密折叠的区域，常由多个超二级结构组成，往往具有特定功能。", "kp": "ch04_s0_3"}, {"id": "ch04_judge_6", "modI": 0, "q": "四级结构指两个或多个具有独立三级结构的亚基通过非共价键组装成的特定空间排列。", "a": "对", "e": "四级结构由多个亚基通过非共价键（氢键、离子键、范德华力、疏水作用等）组装而成，亚基可相同或不同。", "kp": "ch04_s0_4"}, {"id": "ch04_judge_7", "modI": 0, "q": "X射线晶体衍射法中，蛋白质晶体含大量无序水分子，常占晶胞50%~70%，保证晶体中结构与溶液结构相似。", "a": "对", "e": "蛋白质晶体含大量无序水分子，常占晶胞50%~70%，保证晶体中结构与溶液结构相似，且晶体中蛋白质仍可进行催化反应。", "kp": "ch04_s0_5"}, {"id": "ch04_judge_8", "modI": 0, "q": "核磁共振法特别适合长度超过150个氨基酸残基的大蛋白质。", "a": "错", "e": "核磁共振法特别适合长度不超过150个氨基酸残基的小蛋白质，受蛋白质大小限制。", "kp": "ch04_s0_6"}, {"id": "ch04_judge_9", "modI": 0, "q": "冷冻电镜可直接获得分子形态信息，即使在较低分辨率下也能提供有意义的结构信息。", "a": "对", "e": "冷冻电镜可直接获得分子形态信息，即使在较低分辨率下也能提供有意义的结构信息，适于捕捉动态结构变化和解析难以结晶的膜蛋白及大分子复合体。", "kp": "ch04_s0_7"}, {"id": "ch04_judge_10", "modI": 0, "q": "蛋白质对接可以预测两个蛋白质之间是否有相互作用。", "a": "错", "e": "对接只能预测已知有相互作用的蛋白质如何结合，不能预测是否有相互作用。", "kp": "ch04_s0_9"}], "fill": [{"id": "ch04_fill_1", "modI": 0, "q": "蛋白质一级结构指多肽链中氨基酸残基的________，由________共价连接。", "a": "排列顺序,肽键", "kp": "ch04_s0_0"}, {"id": "ch04_fill_2", "modI": 0, "q": "α螺旋每上升一圈约含________个氨基酸残基，螺距约________ nm。", "a": "3.6,0.54", "kp": "ch04_s0_1"}, {"id": "ch04_fill_3", "modI": 0, "q": "β折叠可分为________式和________式，前者相邻肽链同向，后者相邻肽链反向。", "a": "平行,反平行", "kp": "ch04_s0_2"}, {"id": "ch04_fill_4", "modI": 0, "q": "β转角通常由________个氨基酸残基构成，借第1和第4残基之间形成________。", "a": "4,氢键", "kp": "ch04_s0_2"}, {"id": "ch04_fill_5", "modI": 0, "q": "结构域是三级结构中相对独立、紧密折叠的区域，常由多个________组成，往往具有特定________。", "a": "超二级结构,功能", "kp": "ch04_s0_3"}, {"id": "ch04_fill_6", "modI": 0, "q": "四级结构指两个或多个具有独立三级结构的亚基通过________键组装成的特定空间排列。", "a": "非共价", "kp": "ch04_s0_4"}, {"id": "ch04_fill_7", "modI": 0, "q": "Anfinsen原理指出，蛋白质的________决定其特定的空间结构，________折叠形成正确三维结构才使蛋白质具有正常生物学功能。", "a": "一级序列,一级序列", "kp": "ch04_s0_12"}, {"id": "ch04_fill_8", "modI": 0, "q": "蛋白质对接理论上分为________对接、半柔性对接和________对接。", "a": "刚性,柔性", "kp": "ch04_s0_10"}], "short": [{"id": "ch04_short_1", "modI": 0, "q": "简述蛋白质结构层次及其相互关系。", "a": "蛋白质结构层次通常划分为一级、二级、超二级、结构域、三级和四级结构。一级结构指多肽链中氨基酸残基的排列顺序，由肽键共价连接，是决定更高层结构的主要因素；二级结构指主链局部有规律的构象，如α螺旋、β折叠、β转角和无规卷曲；超二级结构指相邻二级结构单元组合成的特定构象；结构域是三级结构中相对独立、常具有特定功能的区域；三级结构是整条肽链所有原子的三维空间排布；四级结构指多个亚基通过非共价键组装成的复合体。若两个蛋白质一级结构显著相似，通常认为它们同源。结构决定功能是蛋白质科学的首要法则。", "kp": "ch04_s0_0"}, {"id": "ch04_short_2", "modI": 0, "q": "简述α螺旋的结构特征及不利于其形成的因素。", "a": "α螺旋是蛋白质中最常见、最典型、含量最丰富的二级结构元件之一，属于重复性结构。其要点包括：主链骨架围绕中心轴盘绕形成右手螺旋；每上升一圈约含3.6个氨基酸残基，螺距约0.54 nm；相邻螺旋圈之间形成氢键，氢键方向大致平行于螺旋轴；侧链基团位于螺旋外侧。不利于α螺旋形成的因素主要有：存在侧链基团较大的氨基酸残基、连续存在带相同电荷的氨基酸残基、脯氨酸等破坏螺旋的残基。α螺旋常见于球状蛋白内部和跨膜蛋白的疏水区段，是结构预测中重点识别的二级结构类型。", "kp": "ch04_s0_1"}, {"id": "ch04_short_3", "modI": 0, "q": "简述β折叠与β转角的区别。", "a": "β折叠由Pauling等提出，是许多蛋白质中常见的二级结构。β折叠可分为平行式和反平行式：平行式中相邻肽链同向，反平行式中相邻肽链反向。每条肽链称为β折叠股，所有肽键的C=O和N—H之间形成链间氢键，侧链基团交替位于片层上下方。β转角常发生于多肽链180°回折处，通常由4个氨基酸残基构成，借第1和第4残基之间形成氢键，形成较稳定的紧密环，多存在于球状蛋白质分子表面，属于非重复性结构。无规卷曲则是主链骨架无规律盘绕的区段，常出现在螺旋与折叠之间，对连接和功能有重要作用。", "kp": "ch04_s0_2"}, {"id": "ch04_short_4", "modI": 0, "q": "简述蛋白质结构比对的目的与意义。", "a": "蛋白质结构比对是对蛋白质三维空间结构的相似性进行比较，是蛋白质结构分析的重要手段。与序列比对相比，结构比对算法更复杂。一个标准的结构比对结果包括：产生参数衡量结构相似性；产生两个蛋白质的序列比对结果，同一比对位置上的氨基酸意味着空间结构相似；产生结构叠加后的PDB文件，可通过图形显示软件观测相似性。结构比对可用于识别同源关系、分析进化关系、预测功能、评估结构预测模型等。常用方法包括基于距离矩阵、基于几何特征等。结构比对是连接序列、结构与功能的重要桥梁。", "kp": "ch04_s0_8"}, {"id": "ch04_short_5", "modI": 0, "q": "简述蛋白质对接的基本原理与分类。", "a": "蛋白质对接是利用计算机预测两个已知结构的蛋白质在空间上如何结合。基本过程：已知两个蛋白质结构，搜索理论上可能产生的数百万个结合构象，利用生物信息学评价标准过滤排除不合理结构，对入围构象用精细能量函数打分，最终确定能量最低的构象。对接准确度取决于搜索结合构象的全面性和能量函数的合理性。搜索和排除主要考虑分子表面几何形状互补性和静电互补性。理论上分为刚性对接、半柔性对接和柔性对接：刚性对接中分子构象不变，仅改变空间位置与姿态，计算量小；半柔性对接允许指定片段构象变化，兼顾计算量与预测能力；柔性对接允许整个体系构象自由变化，计算量极大。", "kp": "ch04_s0_10"}], "calc": [{"id": "ch04_calc_1", "modI": 0, "q": "论述蛋白质折叠的意义、Anfinsen热力学假说及Levinthal悖论，并说明折叠漏斗如何调和热力学与动力学。", "a": "蛋白质折叠是指多肽链自发组装成特定三维空间结构的过程。Anfinsen原理指出，蛋白质的一级序列决定其特定的空间结构，一级序列折叠形成正确三维结构才使蛋白质具有正常生物学功能。若折叠在体内发生故障，形成错误空间结构，不仅丧失功能，还会引起疾病。由蛋白质异常三维结构引发的疾病统称为构象病，包括疯牛病、阿尔茨海默病、囊性纤维病变、家族性高胆固醇症、家族性淀粉样蛋白症、白内障及某些肿瘤等。1963年，美国科学家Anfinsen发现还原变性的牛胰核糖核酸酶在去除变性剂和还原剂后，无需其他物质帮助即可折叠回原来的天然结构，且功能不丧失。由此提出蛋白质折叠的“热力学假说”：小型球状蛋白的天然折叠结构是热力学稳定态，即自由能全局最小状态；蛋白质一级结构序列所提供的全部信息可以完全且唯一地决定分子的天然结构，即一级结构决定高级结构。该假说得到许多体外实验证明，尤其对小分子质量蛋白质。Anfinsen因此获得1972年诺贝尔化学奖。1968年，Cyrus Levinthal提出利文索尔悖论：一条蛋白质序列可能的空间构象数天文数字，若逐一尝试所有构象寻找唯一天然态，所需时间远超宇宙年龄。例如100个氨基酸、每个3种构象，则有3^100种可能，每尝试一次耗10^-13秒，需3^100×10^-13秒，约10^34年。然而体外观测到的折叠时间为毫秒至秒，因此Levinthal认为蛋白质折叠必然按特定路径进行，强调动力学控制的重要性。1995年Wolynes等提出蛋白质折叠漏斗概念，调和热力学与动力学：漏斗状能量景观引导折叠快速趋向天然态，而非随机搜索。", "steps": "1. 蛋白质折叠定义与意义；2. Anfinsen热力学假说内容与实验依据；3. Levinthal悖论的计算与含义；4. 折叠漏斗概念及其对热力学与动力学的调和。", "kp": "ch04_s0_14"}, {"id": "ch04_calc_2", "modI": 0, "q": "论述蛋白质结构预测的意义、主要方法及面临的挑战，并说明其在疾病研究中的应用。", "a": "蛋白质结构预测旨在从氨基酸序列预测三维结构，弥补实验测定结构数量远少于序列数量的缺口。实验方法如X射线晶体衍射、NMR、冷冻电镜虽能获得高分辨率结构，但耗时、昂贵且受样品限制。理论预测方法包括同源建模、折叠识别、从头预测等。同源建模基于序列相似性，适用于有同源结构的情况；折叠识别适用于序列相似性低但结构相似的情况；从头预测基于物理化学原理和能量函数。近年来深度学习方法如AlphaFold取得突破。结构预测有助于功能注释、药物设计、蛋白质改造。但准确预测仍面临构象搜索空间巨大、能量函数不完善等挑战。蛋白质错误折叠与构象病密切相关，结构预测可用于研究疾病机制。例如，预测突变对蛋白质结构稳定性的影响，识别致病构象变化；预测淀粉样纤维形成倾向；设计稳定化突变以治疗构象病。此外，结构预测有助于理解蛋白质-蛋白质相互作用异常在疾病中的作用，为药物设计提供靶点。结合分子动力学模拟，可研究折叠路径和中间体。生物信息学工具如PolyPhen、SIFT可预测突变有害性。结构预测与实验方法结合，可加速疾病相关蛋白质的结构解析和药物开发。", "steps": "1. 结构预测的意义与实验方法局限；2. 主要预测方法：同源建模、折叠识别、从头预测、深度学习；3. 挑战：构象搜索空间、能量函数；4. 在疾病研究中的应用：突变影响、淀粉样纤维、稳定化突变、药物靶点、与实验结合。", "kp": "ch04_s0_16"}], "term": [{"id": "ch04_term_1", "modI": 0, "term": "Protein primary structure", "def": "蛋白质一级结构：指多肽链中氨基酸残基的线性排列顺序；由肽键共价连接；是决定更高层次结构的主要因素；序列相似性常用于推断同源性。", "kp": "ch04_s0_14"}, {"id": "ch04_term_2", "modI": 0, "term": "Protein secondary structure", "def": "蛋白质二级结构：指主链局部有规律的构象；常见类型包括α螺旋、β折叠、β转角和无规卷曲；主要由主链原子间氢键维持；是结构预测中重点识别的元件。", "kp": "ch04_s0_13"}, {"id": "ch04_term_3", "modI": 0, "term": "α-helix", "def": "α螺旋：蛋白质中常见且含量丰富的二级结构元件；主链骨架围绕中心轴形成右手螺旋；每圈约3.6个氨基酸残基，螺距约0.54 nm；相邻螺旋圈之间形成氢键，氢键方向大致平行于螺旋轴；侧链基团位于螺旋外侧；连续相同电荷残基、大侧链残基和脯氨酸不利于其形成。", "kp": "ch04_s0_2"}, {"id": "ch04_term_4", "modI": 0, "term": "β-sheet", "def": "β折叠：由Pauling等提出的常见二级结构；可分为平行式和反平行式；平行式中相邻肽链同向，反平行式中相邻肽链反向；每条肽链称为β折叠股；所有肽键的C=O和N—H之间形成链间氢键；侧链基团交替位于片层上下方。", "kp": "ch04_s0_17"}, {"id": "ch04_term_5", "modI": 0, "term": "β-turn", "def": "β转角：常发生于多肽链180°回折处；通常由4个氨基酸残基构成；借第1和第4残基之间形成氢键；形成较稳定的紧密环；多存在于球状蛋白质分子表面；属于非重复性结构。", "kp": "ch04_s0_0"}, {"id": "ch04_term_6", "modI": 0, "term": "Supersecondary structure", "def": "超二级结构：介于二级结构和三级结构之间的组织层次；指若干相邻二级结构单元在空间上组合成特定的、可识别的构象单元；如βαβ、β发夹、螺旋-转角-螺旋等。", "kp": "ch04_s0_13"}, {"id": "ch04_term_7", "modI": 0, "term": "Protein domain", "def": "结构域：三级结构中相对独立、紧密折叠的区域；常由多个超二级结构组成；往往具有特定功能，如结合配体、催化反应等；是蛋白质功能与进化的基本单位之一；可通过序列比对和结构比较识别；结构域之间常由铰链区连接，允许相对运动。", "kp": "ch04_s0_13"}, {"id": "ch04_term_8", "modI": 0, "term": "Protein tertiary structure", "def": "蛋白质三级结构：指整条多肽链中所有原子的三维空间排布；是在二级结构和超二级结构基础上进一步折叠形成的完整构象；由一级结构决定，但受分子伴侣、环境条件等影响。", "kp": "ch04_s0_14"}, {"id": "ch04_term_9", "modI": 0, "term": "Protein quaternary structure", "def": "蛋白质四级结构：指两个或多个具有独立三级结构的亚基通过非共价键组装成的特定空间排列；非共价键包括氢键、离子键、范德华力、疏水作用等；亚基之间可相同（同源复合体）或不同（异源复合体）；是许多蛋白质行使功能所必需。", "kp": "ch04_s0_14"}, {"id": "ch04_term_10", "modI": 0, "term": "X-ray crystallography", "def": "X射线晶体衍射法：测定蛋白质三维结构最重要的实验手段之一；利用X射线照射蛋白质晶体，通过衍射图谱计算电子密度，进而构建原子坐标；蛋白质晶体含大量无序水分子，常占晶胞50%~70%；晶体中蛋白质仍可进行催化反应；空间分辨率由X射线波长决定，原子位置精度受晶体衍射能力限制；生产足够量、可溶、稳定、有活性的蛋白质仍是最大难题。", "kp": "ch04_s0_14"}, {"id": "ch04_term_11", "modI": 0, "term": "NMR spectroscopy", "def": "核磁共振法：用于测定溶液中蛋白质的三维构象；特别适合长度不超过150个氨基酸残基的小蛋白质；原理是核磁矩不为零的核在外磁场中发生塞曼分裂，吸收特定射频辐射；不需要制备蛋白质晶体；可测定接近生理状态的溶液构象；能研究蛋白质与小分子作用的动力学过程；也可测定可变形的尾部构象；属于非损伤性测定；常用实验包括TOCSY、NOESY等；受蛋白质大小限制，且需要较高浓度和纯度。", "kp": "ch04_s0_7"}, {"id": "ch04_term_12", "modI": 0, "term": "Cryo-electron microscopy", "def": "冷冻电镜三维重构：由de Rosier和Klug于1968年提出，20世纪80年代趋于成熟；通过电子显微镜获取二维晶体图像，再经计算机图像处理重构三维结构；研究对象包括病毒、膜蛋白、肌丝、蛋白质核酸复合体、亚细胞器等；可直接获得分子形态信息；适于捕捉动态结构变化，也适于解析难以结晶的膜蛋白和大分子复合体；电镜图像包含相位信息，在相位确定上比X射线晶体学更直接方便；已成为继X射线和NMR之后生物大分子结构研究的重要方法。", "kp": "ch04_s0_1"}], "preview": {"main": "本章主线：从蛋白质结构层次出发，理解α螺旋、β折叠、β转角、无规卷曲、超二级结构和结构域等基本概念，掌握X射线晶体衍射、NMR和冷冻电镜等结构测定方法，学习结构比对、蛋白质相互作用与对接，并进一步理解蛋白质折叠、Anfinsen热力学假说、Levinthal悖论、折叠漏斗、分子伴侣、构象病以及结构预测的意义与挑战。", "questions": ["蛋白质一级、二级、超二级、结构域、三级和四级结构分别指什么？它们之间有何关系？", "α螺旋、β折叠、β转角和无规卷曲各有哪些结构特征与形成条件？", "X射线晶体衍射、NMR和冷冻电镜测定蛋白质结构的原理、适用对象和优缺点是什么？", "蛋白质结构比对与序列比对有何不同？结构比对能产生哪些结果、用于哪些分析？", "蛋白质折叠为何能快速完成？Anfinsen热力学假说、Levinthal悖论、折叠漏斗和分子伴侣分别如何解释？"]}, "appcards": [{"front": "应用/分析题：给定一条多肽序列，如何从结构层次上描述其可能形成的α螺旋、β折叠、β转角和无规卷曲？", "back": "蛋白质结构层次包括一级、二级、超二级、结构域、三级和四级结构。二级结构指主链局部有规律构象：α螺旋为右手螺旋，每圈约3.6个残基，螺距约0.54 nm，相邻螺旋圈间形成平行于螺旋轴的氢键，侧链位于螺旋外侧；β折叠由β折叠股组成，分平行和反平行式，链间形成C=O与N—H氢键，侧链交替位于片层上下方；β转角常由4个残基构成，发生于180°回折处，第1和第4残基间形成氢键，多位于球状蛋白表面，属非重复性结构；无规卷曲为主链无规律盘绕区段，常连接螺旋与折叠，对连接和功能有重要作用。", "points": "结构层次；α螺旋特征；β折叠平行/反平行；β转角4残基与氢键；无规卷曲功能", "mod": 0, "modName": "第四章 蛋白质结构预测与分析", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：为什么说‘一级结构决定高级结构’？Anfinsen实验和Levinthal悖论分别说明了什么？", "back": "一级结构指多肽链中氨基酸残基排列顺序，由肽键共价连接，是决定更高层结构的主要因素。Anfinsen发现还原变性的牛胰核糖核酸酶去除变性剂和还原剂后可自发折叠回天然结构并恢复功能，提出热力学假说：小型球状蛋白天然折叠结构是自由能全局最小状态，一级序列信息可完全且唯一决定天然结构。Levinthal悖论指出，若蛋白质随机搜索所有构象，所需时间远超宇宙年龄，但实际折叠为毫秒至秒，说明折叠必然按特定路径进行，强调动力学控制。折叠漏斗概念调和热力学与动力学：漏斗状能量景观引导折叠快速趋向天然态。", "points": "一级结构决定高级结构；Anfinsen热力学假说；Levinthal悖论；折叠漏斗；热力学与动力学统一", "mod": 0, "modName": "第四章 蛋白质结构预测与分析", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：X射线晶体衍射、NMR和冷冻电镜在蛋白质结构测定中的原理、适用对象和优缺点是什么？", "back": "X射线晶体衍射利用X射线照射蛋白质晶体，通过衍射图谱计算电子密度并构建原子坐标，可确定原子精度结构；晶体含大量无序水分子，常占晶胞50%~70%，晶体中蛋白质仍可催化，结构具生物相关性；分辨率受X射线波长和晶体衍射能力限制，难点是获得足量、可溶、稳定、有活性的蛋白质。NMR用于测定溶液中蛋白质三维构象，适合不超过约150个氨基酸残基的小蛋白质，不需晶体，可测接近生理状态构象，能研究与小分子作用动力学及可变形尾部，属非损伤性测定，常用TOCSY、NOESY等，但受蛋白质大小限制且需较高浓度和纯度。冷冻电镜通过电子显微镜获取二维图像再经计算机图像处理重构三维结构，研究对象包括病毒、膜蛋白、肌丝、蛋白质核酸复合体、亚细胞器等，可直接获得分子形态信息，适于捕捉动态变化和解析难结晶膜蛋白及大分子复合体，电镜图像包含相位信息，相位确定比X射线晶体学更直接方便。", "points": "X射线原理与晶体特点；NMR溶液构象与大小限制；冷冻电镜三维重构与适用对象；三种方法比较", "mod": 0, "modName": "第四章 蛋白质结构预测与分析", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：蛋白质结构比对与序列比对相比有何特殊目的和输出？常用结构比对方法有哪些？", "back": "蛋白质结构比对是对三维空间结构相似性进行比较，是结构分析的重要手段。与序列比对相比，结构比对算法更复杂。标准结构比对结果包括：产生参数衡量结构相似性；产生两个蛋白质的序列比对结果，同一比对位置上的氨基酸意味着空间结构相似；产生结构叠加后的PDB文件，可通过图形显示软件观测相似性。结构比对可用于识别同源关系、分析进化关系、预测功能、评估结构预测模型等。常用方法包括基于距离矩阵、基于几何特征等。结构比对是连接序列、结构与功能的重要桥梁。", "points": "结构比对目的；输出三要素；同源/进化/功能/模型评估；基于距离矩阵和几何特征", "mod": 0, "modName": "第四章 蛋白质结构预测与分析", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：蛋白质对接的基本原理是什么？刚性、半柔性和柔性对接有何区别？常用软件各有什么特点？", "back": "蛋白质对接是利用计算机预测两个已知结构的蛋白质在空间上如何结合。基本过程：已知两个蛋白质结构，搜索理论上可能产生的数百万个结合构象，利用生物信息学评价标准过滤排除不合理结构，对入围构象用精细能量函数打分，最终确定能量最低构象。准确度取决于搜索结合构象的全面性和能量函数合理性。搜索和排除主要考虑分子表面几何形状互补性和静电互补性。刚性对接中分子构象不变，仅改变空间位置与姿态，计算量小；半柔性对接允许指定片段构象变化，兼顾计算量与预测能力；柔性对接允许整个体系构象自由变化，计算量极大。常用软件：ZDOCK为刚性对接，可上传PDB文件或输入PDB ID，可选取必需或不允许参与结合的氨基酸，结果通过邮箱返回；GRAMMX为刚性对接，可指定必需参与结合的氨基酸，支持同源多聚对接；HADDOCK为半柔性对接，除几何形状和能量外还参考NMR化学位移扰动、定点突变等实验数据，可进行蛋白质-DNA、蛋白质-RNA、蛋白质-化合物对接；PDBePISA为在线交互式工具，可计算复合体相互作用面的原子数、氨基酸数、面积、溶剂化自由能、氢键、二硫键、盐键、共价键等。注意：对接只能预测已知有相互作用的蛋白质如何结合，不能预测是否有相互作用。", "points": "对接基本过程；搜索与能量函数；刚性/半柔性/柔性区别；ZDOCK、GRAMMX、HADDOCK、PDBePISA特点；不能预测是否有相互作用", "mod": 0, "modName": "第四章 蛋白质结构预测与分析", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：蛋白质错误折叠如何导致构象病？分子伴侣和结构预测在疾病研究中有什么作用？", "back": "蛋白质折叠是多肽链自发组装成特定三维空间结构的过程。Anfinsen原理指出一级序列决定特定空间结构，正确折叠才使蛋白质具有正常生物学功能。若折叠在体内发生故障，形成错误空间结构，不仅丧失功能，还会引起疾病。由蛋白质异常三维结构引发的疾病统称为构象病，包括疯牛病、阿尔茨海默病、囊性纤维病变、家族性高胆固醇症、家族性淀粉样蛋白症、白内障及某些肿瘤等，与错误折叠、聚集或构象改变密切相关。许多蛋白质在体内折叠需要分子伴侣帮助，分子伴侣协助正确折叠、组装、转运和降解，但不构成最终结构，常见Hsp70、Hsp60、Hsp90等，通过识别暴露疏水表面防止错误聚集，提供隔离环境促进正确折叠，消耗ATP，属主动过程；PDI和PPI也协助折叠。结构预测可用于研究疾病机制，如预测突变对结构稳定性的影响、识别致病构象变化、预测淀粉样纤维形成倾向、设计稳定化突变，并有助于理解蛋白质-蛋白质相互作用异常，为药物设计提供靶点；结合分子动力学模拟可研究折叠路径和中间体，PolyPhen、SIFT可预测突变有害性。", "points": "折叠与构象病；Anfinsen原理；分子伴侣Hsp70/Hsp60/Hsp90、PDI/PPI；结构预测与疾病研究；PolyPhen/SIFT", "mod": 0, "modName": "第四章 蛋白质结构预测与分析", "level": "掌握", "src": "生成"}]};